// NEET UG Biology: Photosynthesis in higher plants (NCERT Class 11, Chapter 11). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `ps-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function nat(level, sub, q, answer, sol, trap, unit) {
  items.push({ id: nid(), type: 'nat', level, format: 'integer', exams: E, sub, q, answer, tol: 0, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
}
// ---------------------------------------------------------------- Level 1
mc(1, 'early experiments', 'Which scientist showed that a mint plant could restore air that had been spoiled by a burning candle?', 'Joseph Priestley', ['Jan Ingenhousz', 'Julius von Sachs', 'T. W. Engelmann'], 'Priestley (1770) put a candle and later a mouse in a closed jar and found that a mint plant kept the air fit for burning and breathing.');
mc(1, 'early experiments', 'Priestley’s experiment was repeated by Jan Ingenhousz, who showed that', 'sunlight is essential and only the green parts of a plant release oxygen', ['plants release oxygen even in the dark', 'roots release oxygen in sunlight', 'carbon dioxide is released by green parts in light'], 'Ingenhousz (1779) used an aquatic plant in a transparent jar. Bubbles of oxygen came from the green parts in sunlight, not in the dark or from the non-green parts.');
mc(1, 'early experiments', 'Julius von Sachs (1854) found that green parts of plants make', 'glucose, which is stored as starch', ['protein, which is stored as gluten', 'fat, which is stored as oil', 'only oxygen'], 'Sachs showed that glucose is made in green parts and that it is usually stored as starch.');
mc(1, 'early experiments', 'Using a prism and the green alga Cladophora with aerobic bacteria, T. W. Engelmann found the first', 'action spectrum of photosynthesis', ['photolysis of water', 'C4 pathway', 'Calvin cycle'], 'Bacteria gathered in the blue and red regions where the alga released most oxygen. This gave the first action spectrum, which matched the absorption of chlorophylls.');
mc(1, 'chloroplast', 'In a chloroplast, the enzymes for synthesis of sugars are present in the', 'stroma', ['grana', 'thylakoid lumen', 'outer membrane'], 'The stroma holds the enzymes of the Calvin cycle. The membranes of the grana hold the pigments and electron carriers of the light reaction.');
mc(1, 'chloroplast', 'The stacked, coin-like membranous discs inside a chloroplast are called', 'grana', ['stroma', 'cristae', 'stromatolites'], 'A granum is a stack of flattened thylakoids. Stroma lamellae join the grana.');
mc(1, 'pigments', 'The main pigment that takes part directly in photosynthesis is', 'chlorophyll a', ['chlorophyll b', 'xanthophyll', 'carotene'], 'Chlorophyll a is the reaction-centre pigment. The others are accessory pigments.');
mc(1, 'pigments', 'In a paper chromatogram of leaf pigments, chlorophyll a appears', 'bright or blue green', ['yellow green', 'yellow', 'yellow to yellow-orange'], 'Chlorophyll a is bright or blue green, chlorophyll b is yellow green, xanthophylls are yellow and carotenoids are yellow to yellow-orange.');
mc(1, 'light reaction', 'The oxygen released in photosynthesis comes from', 'water', ['carbon dioxide', 'glucose', 'chlorophyll'], 'Water is split during the light reaction. Van Niel’s work on sulphur bacteria and later labelled-oxygen studies showed this.');
mc(1, 'light reaction', 'The products of the light reaction that are used in the Calvin cycle are', 'ATP and NADPH', ['ATP and NADH', 'glucose and oxygen', 'RuBP and CO<sub>2</sub>'], 'ATP and NADPH are the assimilatory power that drives the Calvin cycle.');
mc(1, 'Calvin cycle', 'The first stable product of CO<sub>2</sub> fixation in the Calvin cycle is', '3-phosphoglyceric acid (PGA)', ['oxaloacetic acid', 'ribulose bisphosphate', 'phosphoenol pyruvate'], 'RuBP combines with CO<sub>2</sub> to give two molecules of 3-PGA, a 3-carbon acid. So the cycle is called the C3 pathway.');
mc(1, 'Calvin cycle', 'The enzyme that fixes CO<sub>2</sub> in the C3 pathway is', 'RuBisCO', ['PEP carboxylase', 'hexokinase', 'ATP synthase'], 'RuBisCO is ribulose bisphosphate carboxylase-oxygenase, the most abundant enzyme on earth.');
mc(1, 'C4 pathway', 'The primary CO<sub>2</sub> acceptor in C4 plants is', 'phosphoenol pyruvate (PEP)', ['ribulose bisphosphate', 'oxaloacetic acid', '3-PGA'], 'PEP is a 3-carbon compound in the mesophyll cells. PEP carboxylase adds CO<sub>2</sub> to give oxaloacetic acid (4C).');
mc(1, 'C4 pathway', 'Which of these is a C4 plant?', 'Maize', ['Wheat', 'Rice', 'Potato'], 'Maize, sorghum and sugarcane are C4 plants. Wheat, rice and potato are C3 plants.');
mc(1, 'factors', 'Blackman’s law of limiting factors says that when several factors control a process, its rate is decided by the factor that is', 'nearest to its minimum value', ['at its maximum value', 'present in the largest amount', 'the most recently changed'], 'Blackman (1905) stated that the factor in shortest supply sets the rate.');
mc(1, 'factors', 'The percentage of CO<sub>2</sub> in the atmosphere is about', '0.03 to 0.04', ['0.3 to 0.4', '3 to 4', '21'], 'The air holds only 0.03 to 0.04 per cent CO<sub>2</sub>. So CO<sub>2</sub> is often a limiting factor.');
mc(1, 'photorespiration', 'Photorespiration in C3 plants happens when RuBisCO binds', 'oxygen instead of carbon dioxide', ['nitrogen instead of oxygen', 'water instead of oxygen', 'glucose instead of RuBP'], 'RuBisCO has both carboxylase and oxygenase activity. At low CO<sub>2</sub> and high O<sub>2</sub> it adds O<sub>2</sub> to RuBP.');
mc(1, 'photosynthesis basics', 'The overall equation of photosynthesis gives, for every glucose formed, how many molecules of O<sub>2</sub>?', 'Six', ['Three', 'Twelve', 'One'], '6CO<sub>2</sub> + 12H<sub>2</sub>O → C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6H<sub>2</sub>O + 6O<sub>2</sub>.');

// ---------------------------------------------------------------- Level 2
mc(2, 'early experiments', 'Cornelius van Niel concluded that the oxygen of photosynthesis comes from water. His evidence was from', 'purple and green sulphur bacteria using H<sub>2</sub>S', ['Chlorella grown with labelled carbon', 'a mint plant and a candle', 'Cladophora under a prism'], 'These bacteria use H<sub>2</sub>S and release sulphur, not oxygen. By analogy, green plants use H<sub>2</sub>O and release O<sub>2</sub>.', 'Chlorella with <sup>14</sup>C was Calvin’s work on the carbon path, not the source of oxygen.');
mc(2, 'early experiments', 'The path of carbon in photosynthesis was traced using radioactive <sup>14</sup>C by', 'Melvin Calvin', ['Hatch and Slack', 'Priestley', 'Blackman'], 'Calvin used the alga Chlorella and found the first product to be 3-PGA. Hatch and Slack worked out the C4 pathway.');
mc(2, 'early experiments', 'Which pairing of scientist and finding is wrong?', 'Sachs: oxygen is released from water', ['Priestley: plants restore air spoiled by burning', 'Ingenhousz: light is needed for purification of air', 'Engelmann: red and blue light are most effective'], 'Sachs showed glucose and starch formation in green parts. The water origin of oxygen is linked to van Niel.');
mc(2, 'pigments', 'The pigments that act as accessory pigments include', 'chlorophyll b, xanthophylls and carotenoids', ['chlorophyll a only', 'phycobilins only', 'cytochromes and plastocyanin'], 'They absorb light at other wavelengths and pass the energy to chlorophyll a. They also protect chlorophyll a from photo-oxidation.');
mc(2, 'pigments', 'Chlorophyll a absorbs most strongly in the', 'blue and red regions', ['green and yellow regions', 'green and far-red regions', 'ultraviolet only'], 'The absorption peaks of chlorophyll a are in the blue and red parts of the spectrum. Green light is mostly reflected.');
mc(2, 'pigments', 'An action spectrum of photosynthesis is a graph of', 'rate of photosynthesis against wavelength of light', ['light absorbed against wavelength by one pigment', 'rate of photosynthesis against CO<sub>2</sub> level', 'oxygen release against temperature'], 'The absorption spectrum shows how much a pigment absorbs. The action spectrum shows how well each wavelength drives photosynthesis.', 'Do not mix the two spectra.');
mc(2, 'chloroplast', 'The light reaction takes place in the', 'thylakoid membranes of the grana', ['stroma', 'outer chloroplast membrane', 'cytoplasm'], 'Pigments, photosystems, electron carriers and ATP synthase are on the thylakoid membranes.');
mc(2, 'light reaction', 'The reaction centre of photosystem I is chlorophyll a with absorption peak at', '700 nm', ['680 nm', '430 nm', '660 nm only'], 'PS I has P700 and PS II has P680.');
mc(2, 'light reaction', 'The reaction centre of photosystem II is called', 'P680', ['P700', 'P430', 'P560'], 'P680 is chlorophyll a with the peak at 680 nm.');
mc(2, 'light reaction', 'Light-harvesting complexes (antennae) are made of', 'hundreds of pigment molecules bound to proteins', ['one chlorophyll a molecule', 'only carotenoids', 'ATP synthase subunits'], 'The antennae gather light and funnel energy to the single reaction-centre chlorophyll a of each photosystem.');
mc(2, 'light reaction', 'The photolysis of water is linked with', 'photosystem II on the lumen side', ['photosystem I on the stroma side', 'the Calvin cycle', 'cytochrome c'], 'The water-splitting complex lies on the inner (lumen) side of the thylakoid membrane and supplies electrons to PS II.');
mc(2, 'light reaction', 'Ions needed for the splitting of water include', 'Mn<sup>2+</sup>, Ca<sup>2+</sup> and Cl<sup>−</sup>', ['Fe<sup>2+</sup> and K<sup>+</sup> only', 'Mg<sup>2+</sup> and Na<sup>+</sup> only', 'Cu<sup>2+</sup> and Zn<sup>2+</sup> only'], 'The oxygen-evolving complex needs manganese, calcium and chloride ions.');
mc(2, 'light reaction', 'In the Z scheme, the electron from PS II reaches PS I through', 'plastoquinone, cytochrome b<sub>6</sub>f complex and plastocyanin', ['ferredoxin, NADP reductase and plastocyanin', 'ubiquinone, cytochrome c and cytochrome oxidase', 'cytochrome c only'], 'The order is PS II → primary acceptor → plastoquinone → cyt b<sub>6</sub>f → plastocyanin → PS I.');
mc(2, 'light reaction', 'NADP<sup>+</sup> is reduced to NADPH by the enzyme', 'NADP reductase', ['NADH dehydrogenase', 'ATP synthase', 'RuBisCO'], 'NADP reductase is on the stroma side of the thylakoid membrane. It takes electrons from ferredoxin and protons from the stroma.');
mc(2, 'light reaction', 'Cyclic photophosphorylation produces', 'only ATP', ['only NADPH', 'ATP, NADPH and O<sub>2</sub>', 'NADPH and O<sub>2</sub>'], 'Only PS I is involved. No water is split, so no oxygen. There is no net reduction of NADP<sup>+</sup>.');
mc(2, 'light reaction', 'Cyclic photophosphorylation occurs mainly in', 'stroma lamellae', ['the grana, with PS II', 'the matrix', 'the cytoplasm'], 'Stroma lamellae have PS I but lack PS II and NADP reductase.');
mc(2, 'chemiosmosis', 'ATP synthase of the chloroplast has two parts, CF<sub>0</sub> and CF<sub>1</sub>. CF<sub>1</sub> is', 'the part that sticks out on the stroma side and makes ATP', ['the channel for protons in the membrane', 'a part of PS I', 'on the lumen side only'], 'CF<sub>0</sub> is the transmembrane channel. The CF<sub>1</sub> head makes ATP when protons flow through.');
mc(2, 'chemiosmosis', 'During photosynthetic chemiosmosis, protons accumulate in the', 'thylakoid lumen', ['stroma', 'intermembrane space of the chloroplast', 'cytoplasm'], 'Water splitting and the PQ carrier add H<sup>+</sup> to the lumen. The pH of the lumen is lower than that of the stroma.');
mc(2, 'Calvin cycle', 'The three stages of the Calvin cycle in order are', 'carboxylation, reduction, regeneration', ['reduction, carboxylation, regeneration', 'regeneration, reduction, carboxylation', 'carboxylation, regeneration, reduction'], 'CO<sub>2</sub> is first fixed, the PGA is reduced to triose phosphate, and RuBP is regenerated.');
mc(2, 'Calvin cycle', 'For each CO<sub>2</sub> fixed in the Calvin cycle the plant uses', '3 ATP and 2 NADPH', ['2 ATP and 3 NADPH', '1 ATP and 1 NADPH', '2 ATP and 2 NADPH'], 'Two ATP and two NADPH for reduction, plus one ATP for regeneration of RuBP.', 'Do not forget the ATP of the regeneration step.');
mc(2, 'Calvin cycle', 'RuBP is a', '5-carbon sugar with two phosphates', ['3-carbon acid', '4-carbon acid', '6-carbon sugar'], 'Ribulose 1,5-bisphosphate is a pentose.');
mc(2, 'C4 pathway', 'Leaves of C4 plants show', 'Kranz anatomy with large bundle sheath cells around vascular bundles', ['one layer of palisade cells only', 'no bundle sheath', 'sunken stomata only'], '“Kranz” means wreath. The bundle sheath cells are arranged like a wreath around the vein.');
mc(2, 'C4 pathway', 'In a C4 plant the Calvin cycle takes place in', 'bundle sheath cells', ['mesophyll cells', 'guard cells', 'epidermal cells'], 'PEP carboxylase works in the mesophyll. CO<sub>2</sub> is released in the bundle sheath, where RuBisCO is present.');
mc(2, 'C4 pathway', 'PEP carboxylase has a high affinity for CO<sub>2</sub> and', 'does not react with O<sub>2</sub>', ['also fixes O<sub>2</sub>', 'is found only in bundle sheath cells', 'needs light directly'], 'PEPcase is specific to CO<sub>2</sub>. It works in the mesophyll cells, where RuBisCO is absent.');
mc(2, 'photorespiration', 'In photorespiration, the pathway does not give', 'sugars, ATP or NADPH', ['CO<sub>2</sub>', 'phosphoglycolate', 'a 3-PGA molecule'], 'It releases CO<sub>2</sub> and uses ATP and NADPH instead of making them. It is a wasteful side reaction.');
mc(2, 'photorespiration', 'Photorespiration involves which three cell organelles?', 'Chloroplast, peroxisome and mitochondrion', ['Chloroplast, ribosome and nucleus', 'Peroxisome, Golgi body and vacuole', 'Mitochondrion, lysosome and ER'], 'Phosphoglycolate made in the chloroplast is processed in peroxisomes and mitochondria with release of CO<sub>2</sub>.');
mc(2, 'factors', 'In light as a limiting factor, a graph of photosynthetic rate against light intensity', 'rises linearly at low light and then flattens at saturation', ['rises forever', 'falls steadily', 'is flat from the start'], 'At low light the rate is proportional to intensity. Then another factor, such as CO<sub>2</sub>, becomes limiting.');
mc(2, 'factors', 'In most plants, light saturation is reached at about', '10 per cent of full sunlight', ['100 per cent of full sunlight', '50 per cent of full sunlight', '1 per cent of full sunlight'], 'Except in very shaded or very bright places, about 10 per cent of full sunlight saturates photosynthesis.');
mc(2, 'factors', 'Greenhouse crops such as tomato and bell pepper are grown in CO<sub>2</sub>-enriched air because', 'their photosynthesis rises with more CO<sub>2</sub> and gives higher yield', ['they are C4 plants', 'they cannot use atmospheric CO<sub>2</sub>', 'CO<sub>2</sub> lowers the temperature'], 'They are C3 plants and respond to increased CO<sub>2</sub> up to saturation.');
mc(2, 'factors', 'The CO<sub>2</sub> level at which C3 plants reach saturation is nearly', '450 µL/L', ['360 µL/L', '100 µL/L', '1000 µL/L'], 'C4 plants saturate at about 360 µL/L while C3 plants respond to higher levels, with saturation near 450 µL/L.');
mc(2, 'factors', 'The dark reaction of photosynthesis is more strongly affected by temperature than the light reaction because', 'it is controlled by enzymes', ['it needs light', 'it occurs in grana', 'it makes oxygen'], 'The Calvin cycle is enzyme-catalysed, so temperature affects it. The light reaction is photochemical.');

// ---------------------------------------------------------------- Level 3
mc(3, 'Calvin cycle', 'How many turns of the Calvin cycle are needed to make one molecule of glucose?', 'Six', ['One', 'Three', 'Twelve'], 'Each turn fixes one CO<sub>2</sub>. Glucose has six carbon atoms, so six turns.');
mc(3, 'Calvin cycle', 'The ATP and NADPH needed to make one glucose in the C3 cycle are', '18 ATP and 12 NADPH', ['12 ATP and 18 NADPH', '12 ATP and 12 NADPH', '30 ATP and 12 NADPH'], '6 CO<sub>2</sub> × (3 ATP and 2 NADPH) = 18 ATP and 12 NADPH.', 'The 30 ATP figure is for the C4 pathway.');
mc(3, 'C4 pathway', 'The ATP and NADPH needed to make one glucose in a C4 plant are', '30 ATP and 12 NADPH', ['18 ATP and 12 NADPH', '24 ATP and 12 NADPH', '30 ATP and 18 NADPH'], 'The C4 cycle uses 2 extra ATP per CO<sub>2</sub> to regenerate PEP. So 5 ATP and 2 NADPH per CO<sub>2</sub>, or 30 ATP and 12 NADPH per glucose.');
mc(3, 'light reaction', 'Splitting of two molecules of water gives', '4 H<sup>+</sup>, 4 electrons and one O<sub>2</sub>', ['2 H<sup>+</sup>, 2 electrons and one O<sub>2</sub>', '4 H<sup>+</sup>, 2 electrons and two O<sub>2</sub>', '2 H<sup>+</sup>, 4 electrons and one O<sub>2</sub>'], '2H<sub>2</sub>O → 4H<sup>+</sup> + O<sub>2</sub> + 4e<sup>−</sup>.');
mc(3, 'light reaction', 'In non-cyclic photophosphorylation the electron lost by PS II is replaced by electrons from', 'splitting of water', ['PS I', 'NADPH', 'cytochrome c'], 'The electron lost by P680 is replaced from water. The electron lost by P700 is replaced from PS II through the carriers.');
mc(3, 'light reaction', 'In the Z scheme, the electron lost by P700 is', 'passed to ferredoxin and then to NADP<sup>+</sup> in non-cyclic flow', ['replaced by electrons from water directly', 'passed to cyt b<sub>6</sub>f and then to PS II', 'passed to plastocyanin and then to PS II'], 'In non-cyclic flow, the electron from PS I reaches NADP<sup>+</sup> via an acceptor and ferredoxin.');
mc(3, 'light reaction', 'The Z scheme is so called because', 'the path of electrons on a redox-potential scale looks like the letter Z', ['it involves zinc', 'it was proposed by Z. Hill', 'the electron zigzags between two membranes'], 'The electrons are lifted twice, at PS II and PS I, and run down in between. The curve shape resembles a Z lying on its side.');
mc(3, 'light reaction', 'Which statement about photosystems is true?', 'PS I is in stroma lamellae and non-appressed parts, PS II is in appressed regions of the grana', ['PS II is in stroma lamellae only', 'both are in the stroma', 'PS I is in the lumen'], 'Appressed membranes of the grana hold PS II. Non-appressed parts, such as stroma lamellae, hold PS I and ATP synthase.');
mc(3, 'chemiosmosis', 'Which of these helps build the proton gradient in the thylakoid lumen?', 'Splitting of water and movement of protons by plastoquinone', ['Reduction of NADP<sup>+</sup> on the lumen side', 'Release of protons by RuBisCO', 'Diffusion of protons through CF<sub>0</sub> into the lumen'], 'Water splits in the lumen, and the carrier moves protons from the stroma to the lumen. NADP reductase removes protons from the stroma, which adds to the gradient.', 'NADP reductase works on the stroma side.');
mc(3, 'chemiosmosis', 'ATP is made when protons', 'flow from the lumen to the stroma through CF<sub>0</sub>', ['flow from the stroma to the lumen through CF<sub>1</sub>', 'are pumped by ATP synthase into the lumen', 'combine with oxygen in the lumen'], 'The proton gradient breaks down through the CF<sub>0</sub> channel. The change in shape of CF<sub>1</sub> makes ATP.');
mc(3, 'light reaction', 'Cyclic photophosphorylation is likely to take place when', 'only light of wavelengths beyond 680 nm is available', ['light of all wavelengths is present', 'NADP<sup>+</sup> is plentiful', 'only blue light is present'], 'PS II cannot be excited beyond 680 nm, while PS I can. So electrons cycle around PS I and make ATP.');
mc(3, 'Calvin cycle', 'In the reduction stage of the Calvin cycle, 3-PGA is converted to', 'triose phosphate (PGAL) using ATP and NADPH', ['RuBP using ATP only', 'oxaloacetate using NADPH only', 'glycolate using O<sub>2</sub>'], 'PGA is first phosphorylated by ATP and then reduced by NADPH to a 3-carbon sugar phosphate.');
mc(3, 'Calvin cycle', 'In regenerating RuBP for the Calvin cycle, the step that needs ATP is', 'phosphorylation of ribulose 5-phosphate', ['carboxylation of RuBP', 'reduction of PGA by NADPH', 'splitting of water'], 'One ATP phosphorylates ribulose 5-phosphate to give RuBP.');
mc(3, 'Calvin cycle', 'Out of 6 molecules of triose phosphate made from 3 CO<sub>2</sub>, how many are taken out as the net gain?', 'One', ['Two', 'Three', 'Five'], 'Three CO<sub>2</sub> fixed by three RuBP (15 C) give 6 triose phosphates (18 C). Five (15 C) rebuild 3 RuBP and one (3 C) is the net gain.');
mc(3, 'Calvin cycle', 'RuBisCO is unusual because', 'it acts as both carboxylase and oxygenase', ['it needs no metal ion', 'it is found only in C4 plants', 'it is a membrane enzyme of grana'], 'It binds CO<sub>2</sub> or O<sub>2</sub> at the same active site. So it is a carboxylase-oxygenase.');
mc(3, 'C4 pathway', 'In C4 plants, the 4-carbon acid made first is', 'oxaloacetic acid', ['3-PGA', 'pyruvic acid', 'RuBP'], 'PEP + CO<sub>2</sub> → OAA (4C), which is turned into malic or aspartic acid and transported to the bundle sheath.');
mc(3, 'C4 pathway', 'In the bundle sheath cells of a C4 plant, the 4-carbon acid', 'is broken down to release CO<sub>2</sub> and a 3-carbon pyruvate', ['is reduced to glucose directly', 'is converted to PEP', 'is carboxylated again'], 'The CO<sub>2</sub> enters the Calvin cycle. Pyruvate goes back to the mesophyll, where it becomes PEP.');
mc(3, 'C4 pathway', 'The reason C4 plants show negligible photorespiration is that', 'CO<sub>2</sub> is concentrated around RuBisCO in the bundle sheath', ['they have no RuBisCO', 'they have no oxygen in leaves', 'PEPcase works with O<sub>2</sub>'], 'The C4 cycle raises the CO<sub>2</sub> level at RuBisCO. So the oxygenase activity is suppressed.', 'RuBisCO is present in C4 plants, in the bundle sheath.');
mc(3, 'C4 pathway', 'C4 plants are better adapted than C3 plants to', 'high temperature and low CO<sub>2</sub> with high light', ['low temperature and shade', 'waterlogged soils only', 'dark places'], 'C4 plants have higher optimum temperature (30–45 °C) and use CO<sub>2</sub> efficiently. C3 plants do better at 20–25 °C.');
mc(3, 'C4 pathway', 'The two cell types in a C4 leaf have different chloroplasts, and this is called', 'dimorphism of chloroplasts', ['polymorphism', 'heterospory', 'dichogamy'], 'Mesophyll and bundle sheath cells have chloroplasts that differ in structure and function.');
mc(3, 'photorespiration', 'Which compound is made when RuBisCO adds O<sub>2</sub> to RuBP?', 'Phosphoglycolate and one molecule of 3-PGA', ['Two molecules of 3-PGA', 'Oxaloacetate', 'Two molecules of phosphoglycolate'], 'The oxygenase reaction gives one 3-PGA (3C) and one phosphoglycolate (2C), from the 5 carbons of RuBP.');
mc(3, 'photorespiration', 'Photorespiration is called so because', 'it uses O<sub>2</sub> and releases CO<sub>2</sub> in light, like respiration, but makes no ATP', ['it makes ATP in light', 'it occurs only in the dark', 'it occurs in C4 plants only'], 'It is a light-dependent loss of fixed carbon. It makes no ATP or NADPH.');
mc(3, 'factors', 'Which is correct about light and photosynthesis?', 'Very high light intensity may break down chlorophyll and lower the rate', ['The rate increases with light intensity without limit', 'Rate depends only on the colour of light and not on intensity', 'Light intensity affects only the dark reaction'], 'Beyond saturation, extra light does not raise the rate. Very high light can cause photo-oxidation of pigments.');
mc(3, 'factors', 'In a graph of photosynthetic rate against light, a plant stops responding to more light because', 'CO<sub>2</sub> or another factor has become limiting', ['light has been absorbed by water', 'chlorophyll b increases', 'light is turned into heat only'], 'By Blackman’s law, once light is no longer the factor nearest its minimum, the rate is set by another factor.');
mc(3, 'factors', 'Water stress affects photosynthesis because', 'stomata close, which reduces CO<sub>2</sub> entry, and leaves may wilt and shrink', ['water becomes the fixed carbon source', 'chlorophyll is made in dry air', 'it increases NADPH'], 'Closed stomata cut down CO<sub>2</sub> intake and wilting reduces the leaf surface area.');
mc(3, 'photosynthesis basics', 'The part of sunlight called PAR has wavelengths of', '400–700 nm', ['100–400 nm', '700–1000 nm', '300–500 nm'], 'Photosynthetically active radiation is in the visible range. Plants capture only about 2 to 10 per cent of PAR.');
mc(3, 'photosynthesis basics', 'Only about how much of PAR is captured by plants and used in photosynthesis?', '2 to 10 per cent', ['40 to 50 per cent', '70 to 80 per cent', 'Less than 0.1 per cent'], 'Photosynthesis is a rather low-efficiency conversion, but it supports nearly all life.');
mc(3, 'photosynthesis basics', 'The term “dark reaction” is misleading because', 'the reactions need the ATP and NADPH made in light, and some enzymes are light-activated', ['they take place only at night', 'they happen in the thylakoid membrane', 'they make oxygen'], 'The Calvin cycle is not directly light-driven, but it depends on the light reaction products. It runs in daytime.');
asr(2, 'chloroplast', 'The light reaction takes place on thylakoid membranes.', 'Pigments and electron carriers are embedded in the thylakoid membranes.', 0, 'The membrane-bound photosystems, carriers and ATP synthase explain the location, so R explains A.');
asr(3, 'light reaction', 'Cyclic photophosphorylation does not release oxygen.', 'In cyclic flow, electrons from PS I go back to PS I, and water is not split.', 0, 'Oxygen comes from splitting of water at PS II. Cyclic flow does not involve PS II.');
asr(3, 'C4 pathway', 'C4 plants show almost no photorespiration.', 'CO<sub>2</sub> is concentrated around RuBisCO in the bundle sheath cells of C4 plants.', 0, 'The high CO<sub>2</sub> level at RuBisCO stops it from acting as an oxygenase, so photorespiration is negligible.');
asr(3, 'Calvin cycle', 'Six turns of the Calvin cycle are needed to form one glucose.', 'In each turn one CO<sub>2</sub> is fixed.', 0, 'Glucose has 6 carbons and each turn adds one carbon.');
asr(3, 'pigments', 'Plants look green.', 'Chlorophylls absorb green light strongly.', 2, 'Chlorophylls reflect and transmit green light, and absorb blue and red. So R is false.');
asr(3, 'photorespiration', 'Photorespiration is a wasteful process.', 'It makes neither ATP nor NADPH and releases CO<sub>2</sub>.', 0, 'The carbon already fixed is partly lost and energy is used, so the plant loses efficiency.');
asr(4, 'light reaction', 'In the chloroplast, protons accumulate in the lumen.', 'The NADP reductase is on the lumen side of the thylakoid.', 2, 'A is true. NADP reductase is on the stroma side, and it removes protons from the stroma. R is false.');
asr(4, 'factors', 'The rate of photosynthesis of a plant in bright light may stop rising with a rise in light.', 'According to Blackman, the rate is determined by the factor present at the lowest level relative to need.', 0, 'The limiting factor, such as CO<sub>2</sub>, sets the rate, so more light does not help.');
asr(3, 'C4 pathway', 'CO<sub>2</sub> released inside the bundle sheath cells of a C4 plant does not easily escape.', 'The bundle sheath cells have thick, impervious walls and no intercellular spaces.', 0, 'Thick walls with no gas spaces keep the CO<sub>2</sub> inside for the Calvin cycle, so R explains A.');
stm(2, 'pigments', 'Chlorophyll a is the main pigment of photosynthesis.', 'Carotenoids absorb light and pass it to chlorophyll a.', 0, 'Both are correct. Carotenoids are accessory pigments and also protect against photo-oxidation.');
stm(3, 'light reaction', 'Cyclic photophosphorylation makes NADPH.', 'Non-cyclic photophosphorylation makes both ATP and NADPH.', 3, 'Cyclic flow makes only ATP. Non-cyclic makes ATP, NADPH and O<sub>2</sub>.');
stm(3, 'Calvin cycle', 'The first stable product of the Calvin cycle is a 3-carbon acid.', 'The first stable product of the Hatch-Slack pathway is a 4-carbon acid.', 0, 'PGA is 3C and OAA is 4C. Both are correct.');
stm(3, 'C4 pathway', 'RuBisCO is present in the mesophyll cells of maize.', 'PEPcase is present in the bundle sheath cells of maize.', 1, 'It is the other way round. PEPcase is in the mesophyll and RuBisCO in the bundle sheath.');
stm(3, 'photorespiration', 'In photorespiration, RuBisCO acts as an oxygenase.', 'Photorespiration produces ATP in mitochondria.', 2, 'The first is correct. The process makes no ATP, so the second is wrong.');
stm(3, 'factors', 'Blackman’s law is about several factors that affect a process.', 'The rate is decided by the factor which is closest to its optimum.', 2, 'The rate is decided by the factor nearest to its minimum value (the one in shortest supply), not optimum.');
stm(3, 'early experiments', 'Priestley found that plants release oxygen only in sunlight.', 'Ingenhousz found that only green parts of plants release oxygen in sunlight.', 3, 'Priestley did not know the role of light. Ingenhousz showed that light was needed.');
stm(4, 'chemiosmosis', 'ATP synthase of thylakoids uses the energy of a proton gradient.', 'In the thylakoid, protons are higher in the stroma than the lumen.', 2, 'The first is right. The lumen has higher proton concentration and lower pH.');
match(2, 'early experiments', 'psm1', 'Scientist and contribution', ['A. Priestley', 'B. Ingenhousz', 'C. Sachs', 'D. Engelmann'], ['p. Green parts and sunlight needed to purify air', 'q. Action spectrum with Cladophora and bacteria', 'r. Mint plant, candle and mouse', 's. Glucose stored as starch'], 'A-r, B-p, C-s, D-q', ['A-p, B-r, C-s, D-q', 'A-r, B-p, C-q, D-s', 'A-s, B-p, C-r, D-q'], 'Priestley: mint and candle. Ingenhousz: green parts in sunlight. Sachs: glucose and starch. Engelmann: action spectrum.');
match(3, 'C4 pathway', 'psm2', 'Cell or compound and role in C4 plants', ['A. Mesophyll cell', 'B. Bundle sheath cell', 'C. Oxaloacetic acid', 'D. Pyruvic acid'], ['p. Site of the Calvin cycle', 'q. Site of PEP carboxylase', 'r. First 4-carbon product', 's. Returns to mesophyll to make PEP'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'PEPcase works in mesophyll cells and the Calvin cycle in bundle sheath cells. OAA is the first product. Pyruvate returns to form PEP.');
match(3, 'light reaction', 'psm3', 'Component and location or role', ['A. Photosystem II', 'B. NADP reductase', 'C. ATP synthase CF<sub>1</sub>', 'D. Plastocyanin'], ['p. Stroma side, reduces NADP<sup>+</sup>', 'q. Water splitting on lumen side', 'r. Carrier between cyt b<sub>6</sub>f and PS I', 's. Makes ATP, projects into stroma'], 'A-q, B-p, C-s, D-r', ['A-p, B-q, C-s, D-r', 'A-q, B-p, C-r, D-s', 'A-s, B-p, C-q, D-r'], 'PS II is linked with water splitting. NADP reductase works at the stroma face. CF<sub>1</sub> projects to the stroma. Plastocyanin passes electrons to PS I.');
match(3, 'Calvin cycle', 'psm4', 'Stage of Calvin cycle and event', ['A. Carboxylation', 'B. Reduction', 'C. Regeneration', 'D. Photorespiration'], ['p. Needs ATP and NADPH to make triose phosphate', 'q. RuBisCO adds CO<sub>2</sub> to RuBP', 'r. Ribulose 5-phosphate is phosphorylated to RuBP', 's. RuBisCO adds O<sub>2</sub> to RuBP'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Fixation by RuBisCO is carboxylation. PGA is reduced with ATP and NADPH. Regeneration needs ATP to make RuBP. Oxygenase action starts photorespiration.');
match(4, 'factors', 'psm5', 'Factor and effect', ['A. Light at 10% of full sun', 'B. CO<sub>2</sub> beyond 450 µL/L in C3 plants', 'C. Temperature above 45 °C for C4 plants', 'D. Closure of stomata in drought'], ['p. Saturation of the rate', 'q. Enzymes begin to be damaged, the rate falls', 'r. Fall in CO<sub>2</sub> entry', 's. Rate no longer limited by light'], 'A-s, B-p, C-q, D-r', ['A-p, B-s, C-q, D-r', 'A-s, B-p, C-r, D-q', 'A-q, B-p, C-s, D-r'], 'Around 10 per cent of full sun, light stops being limiting. Above saturation, more CO<sub>2</sub> does not help. High temperature harms enzymes. Closed stomata restrict CO<sub>2</sub>.');

pass('psp1', 'Passage: two leaves', 'A student has two plants, one a C3 plant and one a C4 plant, in a sealed chamber with bright light and a small supply of CO<sub>2</sub>. She measures the CO<sub>2</sub> level in the chamber after some hours. The CO<sub>2</sub> in the chamber falls much lower with plant X than with plant Y. A leaf section of plant X shows a ring of large cells around each vein, in which chloroplasts are packed. The ring is surrounded by loosely arranged cells.');
pq('psp1', 3, 'C4 pathway', 'Plant X is most likely', 'a C4 plant, because the ring of large cells is Kranz anatomy', ['a C3 plant, because it has palisade cells', 'a C3 plant, because it has a bundle sheath', 'a CAM plant, because it has large cells'], 'A wreath of bundle sheath cells packed with chloroplasts is Kranz anatomy. C4 plants can bring CO<sub>2</sub> down to a very low level.');
pq('psp1', 4, 'C4 pathway', 'The first fixation of CO<sub>2</sub> in plant X takes place in', 'the loosely arranged mesophyll cells by PEP carboxylase', ['the bundle sheath cells by RuBisCO', 'the bundle sheath cells by PEP carboxylase', 'the epidermal cells by RuBisCO'], 'PEPcase works in mesophyll cells and gives OAA. The OAA then moves to the bundle sheath.');
pq('psp1', 4, 'photorespiration', 'If the chamber is flooded with high oxygen, the plant that will lose the more fixed carbon is', 'plant Y (C3), because RuBisCO will act as an oxygenase', ['plant X, because PEPcase is blocked by O<sub>2</sub>', 'plant X, because it has no RuBisCO', 'both lose equally'], 'The C3 plant has RuBisCO exposed to chamber air. The C4 plant keeps CO<sub>2</sub> high at RuBisCO.');
pass('psp2', 'Passage: light reaction experiment', 'Isolated thylakoids are kept in a buffer with an electron acceptor but without NADP<sup>+</sup>. They are lit with red light of 710 nm. After some time, ATP is found in the buffer but no oxygen is released and no NADPH is found. When light of 650 nm is used with NADP<sup>+</sup> present, oxygen, ATP and NADPH are all formed.');
pq('psp2', 3, 'light reaction', 'The process at 710 nm is', 'cyclic photophosphorylation', ['non-cyclic photophosphorylation', 'photolysis of water', 'Calvin cycle'], 'Only PS I can absorb beyond 700 nm. With no water splitting, ATP only is made, as in cyclic flow.');
pq('psp2', 4, 'light reaction', 'At 650 nm with NADP<sup>+</sup>, the oxygen released comes from', 'the splitting of water at PS II', ['reduction of NADP<sup>+</sup>', 'ATP synthase', 'cytochrome b<sub>6</sub>f complex'], 'Both photosystems work at 650 nm. PS II splits water to give electrons, protons and O<sub>2</sub>.');
pq('psp2', 4, 'chemiosmosis', 'The ATP in both experiments is formed when', 'protons flow from the lumen to the stroma through ATP synthase', ['protons flow from the stroma to the lumen through CF<sub>1</sub>', 'NADPH is oxidised', 'oxygen is released'], 'Chemiosmosis links electron flow to ATP synthesis in both cyclic and non-cyclic flow.');
pass('psp3', 'Passage: rate and light', 'A graph shows the rate of photosynthesis of a plant against light intensity at two CO<sub>2</sub> levels, 0.03 per cent and 0.05 per cent, at 25 °C. At low light, the two lines overlap and rise together. At higher light, the 0.03 per cent line flattens first and the 0.05 per cent line flattens at a higher value.');
pq('psp3', 3, 'factors', 'At low light intensity the two lines overlap because', 'light is the limiting factor in both', ['CO<sub>2</sub> is the limiting factor in both', 'temperature is the limiting factor', 'water is the limiting factor'], 'Blackman’s law: the rate is set by the factor in shortest supply. Here it is light for both.');
pq('psp3', 4, 'factors', 'At high light, the 0.03 per cent line flattens because', 'CO<sub>2</sub> has become the limiting factor', ['light is still limiting', 'oxygen is limiting', 'chlorophyll is destroyed'], 'The two lines differ only in CO<sub>2</sub>, so the flattening is due to CO<sub>2</sub> limitation.');

// ---------------------------------------------------------------- Level 4
mc(4, 'Calvin cycle', 'For 12 molecules of CO<sub>2</sub> fixed in the Calvin cycle, how many ATP and NADPH are needed?', '36 ATP and 24 NADPH', ['36 ATP and 12 NADPH', '24 ATP and 24 NADPH', '60 ATP and 24 NADPH'], 'Per CO<sub>2</sub>, 3 ATP and 2 NADPH. For 12: 36 ATP and 24 NADPH.');
mc(4, 'Calvin cycle', 'The net gain of carbon by a plant leaf after 3 turns of the Calvin cycle is', 'one triose phosphate (3 carbons)', ['one glucose', 'two triose phosphates', 'one RuBP'], '3 CO<sub>2</sub> + 3 RuBP gives 6 triose phosphates. Five are used to rebuild 3 RuBP. One is net.');
mc(4, 'Calvin cycle', 'When light is suddenly switched off, which compound in the Calvin cycle accumulates?', '3-PGA', ['RuBP', 'Triose phosphate', 'Glucose'], 'With no ATP and NADPH, PGA cannot be reduced, and RuBP is no longer regenerated. RuBP falls and PGA rises.', 'RuBP falls since it is used up and not regenerated.');
mc(4, 'Calvin cycle', 'If CO<sub>2</sub> supply is stopped while light stays on, the level of', 'RuBP rises and PGA falls', ['RuBP falls and PGA rises', 'both rise', 'both fall'], 'RuBP is not used up without CO<sub>2</sub>, and PGA is no longer made, while it continues to be reduced.');
mc(4, 'C4 pathway', 'The overall energy cost per CO<sub>2</sub> fixed in a C4 plant, compared with a C3 plant, is', 'higher by 2 ATP', ['lower by 2 ATP', 'the same', 'higher by 2 NADPH'], 'PEP is regenerated from pyruvate using 2 ATP (as ATP to AMP). This is the cost of concentrating CO<sub>2</sub>.', 'It still pays in hot, bright places because photorespiration is avoided.');
mc(4, 'C4 pathway', 'Which of these shows that C4 plants have an advantage in a hot, dry climate?', 'Stomata can be kept partly closed while CO<sub>2</sub> is still fixed efficiently', ['They have no stomata', 'They fix CO<sub>2</sub> only at night', 'They use no light'], 'PEPcase has a high affinity for CO<sub>2</sub>, so the plant can lose less water and still gain carbon.');
mc(4, 'C4 pathway', 'Select the incorrect statement about C4 plants.', 'Mesophyll cells contain RuBisCO but no PEPcase', ['Bundle sheath cells have thick walls with no intercellular space', 'They have two types of chloroplast', 'Photorespiration is negligible'], 'In C4 plants the mesophyll cells have PEPcase and lack RuBisCO. The option given is the incorrect one.');
mc(4, 'light reaction', 'Which statement about the electron carriers between PS II and PS I is NOT correct?', 'Ferredoxin carries electrons from PS II to cyt b<sub>6</sub>f', ['Plastoquinone also helps move protons into the lumen', 'Plastocyanin is a copper-containing protein', 'Cytochrome b<sub>6</sub>f links plastoquinone and plastocyanin'], 'The chain is PQ → cyt b<sub>6</sub>f → PC. Ferredoxin comes after PS I.');
mc(4, 'light reaction', 'The number of electrons needed to reduce 12 NADP<sup>+</sup> and the number of water molecules split for this are', '24 and 12', ['12 and 12', '24 and 24', '12 and 6'], 'Each NADPH needs 2 electrons, giving 24. Each water gives 2 electrons, so 12 water molecules are split, giving 6 O<sub>2</sub>.');
mc(4, 'light reaction', 'Light of 700 nm alone is given to a leaf. Which is true?', 'PS I works but PS II does not, so only cyclic flow is possible', ['PS II works, giving oxygen', 'Both work equally', 'Neither works'], 'The “red drop” is seen beyond about 680 nm because PS II fails there.');
mc(4, 'light reaction', 'The photosystem that is directly involved in the reduction of NADP<sup>+</sup> is', 'PS I', ['PS II', 'both together in cyclic flow', 'the Calvin cycle'], 'The electron from PS I goes to ferredoxin and then to NADP<sup>+</sup>.');
mc(4, 'chemiosmosis', 'Compared with the stroma, the thylakoid lumen is', 'more acidic, since it has more protons', ['more alkaline', 'the same pH', 'neutral always'], 'Protons are concentrated in the lumen. ATP forms as they flow down the gradient into the stroma.');
mc(4, 'chemiosmosis', 'The difference between chemiosmosis in chloroplasts and in mitochondria is that in chloroplasts', 'protons move into the lumen and flow back to the stroma to make ATP', ['protons accumulate in the intermembrane space', 'ATP is made inside the cristae', 'NADH is the electron donor'], 'In mitochondria, protons are pumped into the intermembrane space and flow back to the matrix. In chloroplasts, the lumen takes the role.');
mc(4, 'photorespiration', 'The key requirement for photorespiration is', 'high O<sub>2</sub> and low CO<sub>2</sub> concentration at RuBisCO', ['high CO<sub>2</sub> and low O<sub>2</sub>', 'dark and low temperature', 'high NADPH only'], 'The two gases compete for the same active site. When O<sub>2</sub> is relatively more, oxygenation wins.');
mc(4, 'photorespiration', 'A scientist raises the CO<sub>2</sub> in the air around a C3 crop to 600 µL/L. Which change is expected?', 'Photorespiration decreases', ['Photorespiration increases', 'PEPcase becomes active in the bundle sheath', 'Stomata open more'], 'CO<sub>2</sub> now wins over O<sub>2</sub> at RuBisCO.');
mc(4, 'factors', 'In an experiment, the rate of photosynthesis remains the same when temperature increases from 15 to 25 °C at low light, but increases at high light. This shows', 'light is limiting at low light, so temperature has no effect there', ['temperature affects only the light reaction', 'light affects the dark reaction only', 'the plant is a C4 plant'], 'At low light the photochemical step limits the rate. At high light the enzyme-controlled step limits it, so temperature matters.');
mc(4, 'factors', 'C3 plants have an optimum temperature of', '20–25 °C', ['30–45 °C', '10–15 °C', '50–60 °C'], 'C4 plants have 30–45 °C. C3 plants show photosynthesis best at 20–25 °C.');
mc(4, 'chloroplast', 'Which pair is correct for the chloroplast?', 'Grana: light reaction; stroma: dark reaction', ['Grana: Calvin cycle; stroma: light reaction', 'Outer membrane: ATP synthase; inner membrane: PS II', 'Thylakoid lumen: Calvin cycle'], 'Membranes of the grana carry the photosystems. Calvin cycle enzymes are in the stroma.');
mc(4, 'pigments', 'The pigment that gives the leaf the yellow colour in autumn once chlorophyll is lost is', 'carotenoid', ['chlorophyll b', 'chlorophyll a', 'plastocyanin'], 'Carotenoids and xanthophylls are masked by chlorophyll until it breaks down.');
mc(4, 'early experiments', 'Which experiment would best show that oxygen comes from water?', 'Giving water with labelled oxygen and finding the label in released O<sub>2</sub>', ['Giving CO<sub>2</sub> with labelled carbon', 'Growing the plant in the dark', 'Measuring starch in leaves'], 'If H<sub>2</sub><sup>18</sup>O is supplied, the released oxygen carries the label. With C<sup>18</sup>O<sub>2</sub> and normal water, it does not.');
mc(4, 'Calvin cycle', 'One molecule of PGAL made in the Calvin cycle costs the plant, in terms of NADPH,', '2 NADPH per CO<sub>2</sub>, so 6 NADPH per PGAL', ['2 NADPH per PGAL', '3 NADPH per PGAL', '12 NADPH per PGAL'], 'A PGAL has 3 carbons, so 3 CO<sub>2</sub> are fixed, using 3 × 2 = 6 NADPH and 3 × 3 = 9 ATP.');
mc(4, 'mixed', 'A plant is moved from light to dark. The gas exchange of its leaf will most likely show', 'net release of CO<sub>2</sub> and uptake of O<sub>2</sub> from respiration', ['net uptake of CO<sub>2</sub>', 'release of O<sub>2</sub> only', 'no gas exchange'], 'Photosynthesis stops, but respiration continues. So the leaf takes up O<sub>2</sub> and releases CO<sub>2</sub>.');
mc(4, 'C4 pathway', 'Regeneration of PEP in the mesophyll is done by', 'pyruvate phosphate dikinase using ATP', ['RuBisCO', 'ATP synthase', 'NADP reductase'], 'Pyruvate from the bundle sheath is phosphorylated to PEP. This step uses ATP.');
stm(4, 'Calvin cycle', 'In the Calvin cycle, carbon dioxide is fixed by combining with a 5-carbon compound.', 'The first product splits into two molecules of a 3-carbon acid.', 0, 'RuBP + CO<sub>2</sub> gives an unstable 6-carbon compound that splits into two PGA molecules. Both statements are correct.');
stm(4, 'C4 pathway', 'Both C3 and C4 plants use the Calvin cycle for fixing CO<sub>2</sub> into sugars.', 'C4 plants use PEPcase to fix CO<sub>2</sub> directly into sugars without the Calvin cycle.', 2, 'In C4 plants, sugars are still made by the Calvin cycle in the bundle sheath. PEPcase only makes the 4-carbon acid.');
stm(4, 'light reaction', 'Plastoquinone shuttles protons across the thylakoid membrane.', 'Ferredoxin is found between cyt b<sub>6</sub>f and PS II.', 2, 'Ferredoxin is after PS I. So statement II is wrong.');
stm(4, 'photorespiration', 'Photorespiration reduces the net photosynthetic output of a C3 plant.', 'It is faster in C4 plants than in C3 plants.', 2, 'It is negligible in C4 plants.');

// ---------------------------------------------------------------- Level 5
mc(5, 'Calvin cycle', 'A C3 leaf makes 5 molecules of glucose. How many ATP are spent in the Calvin cycle for this?', '90', ['60', '180', '150'], '5 glucose = 30 CO<sub>2</sub>, each needing 3 ATP = 90 ATP. (60 NADPH are also used.)');
mc(5, 'C4 pathway', 'A C4 leaf makes 2 glucose. The total ATP and NADPH used are', '60 ATP and 24 NADPH', ['36 ATP and 24 NADPH', '60 ATP and 12 NADPH', '30 ATP and 24 NADPH'], '12 CO<sub>2</sub> × (5 ATP and 2 NADPH).');
mc(5, 'light reaction', 'How many water molecules must be split to supply the NADPH for fixing 6 CO<sub>2</sub> into glucose?', '12', ['6', '24', '18'], '6 CO<sub>2</sub> need 12 NADPH, each taking 2 electrons, so 24 electrons. Each water gives 2 electrons, so 12 H<sub>2</sub>O.', 'Do not confuse this with the 6 O<sub>2</sub> released.');
mc(5, 'light reaction', 'The oxygen released for each glucose made, written as moles of O<sub>2</sub> per mole of CO<sub>2</sub> fixed, is', '1', ['0.5', '2', '6'], 'Net 6 O<sub>2</sub> for 6 CO<sub>2</sub>, or 1 each.');
mc(5, 'chemiosmosis', 'If the thylakoid membranes are made leaky to protons, which is expected?', 'ATP synthesis falls, but electron flow can continue', ['ATP synthesis rises', 'Calvin cycle rises', 'oxygen release stops at once because water splitting needs ATP'], 'Without a gradient, ATP synthase gets no driving force. This is how uncouplers act.');
mc(5, 'chemiosmosis', 'An acid-bath experiment: thylakoids are first soaked at pH 4 and then moved to pH 8 with ADP and phosphate, in darkness. They make ATP because', 'a pH gradient with the lumen acidic drives ATP synthase', ['light is trapped by chlorophyll', 'carbon dioxide is fixed', 'water is split'], 'The artificial gradient replaces the light-driven gradient.', 'No light is needed once the gradient exists.');
mc(5, 'light reaction', 'The DCMU herbicide blocks electron flow from PS II to plastoquinone. Which is expected in a leaf?', 'Non-cyclic flow and O<sub>2</sub> release stop, but cyclic flow at PS I may continue', ['Cyclic flow stops, but O<sub>2</sub> release continues', 'Both stop and CO<sub>2</sub> is fixed faster', 'NADPH is made in larger amounts'], 'DCMU acts after PS II, so non-cyclic flow stops. PS I cyclic flow can go on and make a little ATP.');
mc(5, 'Calvin cycle', 'If the enzyme that regenerates RuBP from ribulose 5-phosphate is blocked, the immediate effect is', 'CO<sub>2</sub> fixation stops after the existing RuBP is used', ['more glucose is made', 'only the light reaction stops', 'PEPcase takes over in the stroma'], 'RuBP is needed as CO<sub>2</sub> acceptor. Without regeneration the cycle stops.');
mc(5, 'photorespiration', 'Which statement about the oxygenase reaction of RuBisCO is correct?', 'It gives a 2-carbon and a 3-carbon product from the 5-carbon RuBP', ['It gives two 3-carbon products', 'It gives two 2-carbon products and one 1-carbon product', 'It gives a 4-carbon product'], '2C phosphoglycolate + 3C PGA = 5 carbons.');
mc(5, 'C4 pathway', 'In an experiment, maize leaves are given <sup>14</sup>CO<sub>2</sub> for a few seconds. The first compound that carries the label is', 'oxaloacetic acid', ['3-PGA', 'triose phosphate', 'RuBP'], 'The first fixation is by PEPcase to give OAA. In a C3 plant it would be PGA.');
mc(5, 'factors', 'A graph shows photosynthesis of a C3 plant and a C4 plant against CO<sub>2</sub>. The C4 curve saturates near 360 µL/L, while the C3 curve keeps rising to about 450 µL/L. At 200 µL/L, which is expected?', 'C4 shows the higher rate', ['C3 shows the higher rate', 'Both show the same rate', 'C4 is zero'], 'C4 plants use low CO<sub>2</sub> better because of the concentrating mechanism.');
mc(5, 'pigments', 'Which statement about the absorption and action spectra is correct?', 'The action spectrum has peaks near those of the absorption spectrum of chlorophyll a, but with some activity from accessory pigments', ['They are identical in all plants', 'The action spectrum has no peak in the blue', 'The absorption spectrum is made with oxygen release'], 'Chlorophyll a peaks in blue and red. Accessory pigments add activity at other wavelengths, so the two curves are not identical.');
mc(5, 'mixed', 'A plant uses 90 ATP in the Calvin cycle. How many glucose molecules were made if it is a C3 plant, and how many if a C4 plant (same ATP)?', '5 (C3) and 3 (C4)', ['5 (C3) and 5 (C4)', '3 (C3) and 5 (C4)', '15 (C3) and 9 (C4)'], 'C3: 18 ATP per glucose, so 90/18 = 5. C4: 30 ATP per glucose, so 90/30 = 3.');
mc(5, 'light reaction', 'Which sequence is correct for non-cyclic electron flow?', 'H<sub>2</sub>O → PS II → PQ → cyt b<sub>6</sub>f → PC → PS I → Fd → NADP<sup>+</sup>', ['H<sub>2</sub>O → PS I → PQ → cyt b<sub>6</sub>f → PC → PS II → NADP<sup>+</sup>', 'H<sub>2</sub>O → PS II → Fd → PC → PS I → NADP<sup>+</sup>', 'NADPH → PS I → cyt b<sub>6</sub>f → PS II → H<sub>2</sub>O'], 'Water gives electrons to PS II, then carriers, PS I, ferredoxin and NADP reductase.');
mc(5, 'chloroplast', 'Which of these is found on the stroma side of the thylakoid membrane?', 'NADP reductase and the CF<sub>1</sub> head of ATP synthase', ['the water-splitting complex', 'free plastocyanin only', 'PS II reaction centre only'], 'The oxygen-evolving complex and plastocyanin are on the lumen side.');
mc(5, 'Calvin cycle', 'How many carbons are present in the compounds that start a Calvin cycle (3 RuBP and 3 CO<sub>2</sub>) and in those that leave as 5 triose phosphates?', '18 carbons and 15 carbons', ['15 carbons and 15 carbons', '18 carbons and 18 carbons', '15 carbons and 18 carbons'], '3 × 5 + 3 = 18. Five triose phosphates carry 5 × 3 = 15, which is turned into 3 RuBP. The 18th carbon is in the sixth triose phosphate, the net gain.');
mc(5, 'C4 pathway', 'A student says that C4 plants do not need RuBisCO. The error is that', 'RuBisCO is present in the bundle sheath cells and fixes CO<sub>2</sub> in the Calvin cycle', ['RuBisCO is present only in mesophyll cells', 'C4 plants have PEPcase in the stroma', 'C4 plants fix CO<sub>2</sub> only at night'], 'C4 plants still use RuBisCO for the final fixation.');
mc(5, 'light reaction', 'Which pair does NOT match?', 'Cyclic flow: needs water splitting', ['Non-cyclic flow: ATP and NADPH', 'Cyclic flow: PS I only', 'Photolysis: lumen side'], 'Cyclic flow makes only ATP and needs no water splitting.');
mc(5, 'factors', 'Plants in a closed greenhouse show falling photosynthesis in the afternoon, even though light is high. The most likely limiting factor is', 'CO<sub>2</sub>', ['light', 'oxygen', 'nitrogen gas'], 'Photosynthesis lowers CO<sub>2</sub> in a closed space. Hence CO<sub>2</sub> enrichment is used.');
mc(5, 'early experiments', 'Which sequence of discoveries is in the correct historical order?', 'Priestley, Ingenhousz, Sachs, Engelmann, Calvin', ['Sachs, Priestley, Ingenhousz, Calvin, Engelmann', 'Engelmann, Priestley, Ingenhousz, Sachs, Calvin', 'Ingenhousz, Priestley, Sachs, Calvin, Engelmann'], '1770, 1779, 1854, 1881 and the 1940s-50s.');
mc(5, 'mixed', 'In which of these will the Calvin cycle slow down first when a leaf is kept in darkness?', 'Reduction of 3-PGA', ['Carboxylation by RuBisCO', 'Diffusion of CO<sub>2</sub>', 'Hydrolysis of starch'], 'Without ATP and NADPH, reduction of PGA stops first, and RuBP regeneration follows.', 'Carboxylation also falls later when RuBP runs out.');
asr(5, 'light reaction', 'Cytochrome b<sub>6</sub>f is called a proton pump in the thylakoid.', 'The movement of electrons through it is linked to movement of protons across the membrane into the lumen.', 0, 'The energy of electron flow is used to move protons, so R explains A.');
asr(5, 'photorespiration', 'Photorespiration occurs in three organelles.', 'The chloroplast, peroxisome and mitochondrion are all needed to process phosphoglycolate.', 0, 'The pathway starts in the chloroplast and passes to peroxisomes and mitochondria, so R explains A.');
asr(4, 'Calvin cycle', 'Three ATP are needed for each CO<sub>2</sub> fixed by the Calvin cycle.', 'Only reduction of PGA requires ATP.', 2, 'Regeneration of RuBP also needs ATP, so R is false.');
nat(3, 'Calvin cycle', 'How many ATP are used in the Calvin cycle (C3) to make 4 molecules of glucose?', 72, '4 glucose = 24 CO<sub>2</sub>. 24 × 3 = 72 ATP.', 'Count per CO<sub>2</sub>, not per glucose, and then multiply.');
nat(3, 'Calvin cycle', 'How many NADPH are used in the Calvin cycle to fix 15 molecules of CO<sub>2</sub>?', 30, 'Each CO<sub>2</sub> needs 2 NADPH, so 15 × 2 = 30.');
nat(4, 'C4 pathway', 'How many ATP are used by a C4 plant (C4 cycle and Calvin cycle together) in fixing 8 molecules of CO<sub>2</sub>?', 40, 'Per CO<sub>2</sub>, 5 ATP (3 in the Calvin cycle and 2 to regenerate PEP). 8 × 5 = 40.');
nat(4, 'light reaction', 'How many molecules of oxygen are released when 24 molecules of NADPH are made by non-cyclic photophosphorylation?', 12, '24 NADPH need 48 electrons. Each O<sub>2</sub> comes with 4 electrons (2H<sub>2</sub>O → O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>−</sup>), so 48 ÷ 4 = 12 O<sub>2</sub>.', 'Each water gives only 2 electrons, so one O<sub>2</sub> needs two waters.');

const gens = [
  { id: 'ps-g01', type: 'nat', level: 3, format: 'integer', exams: E, sub: 'ATP and NADPH counts',
    make(rng) { const k = int(rng, 2, 9); const atp = 18 * k; return { k, q: `How many ATP are used in the Calvin cycle of a C3 plant to make ${k} molecules of glucose?`, answer: atp, tol: 0, sol: `Each glucose needs 6 CO<sub>2</sub> fixed, and each CO<sub>2</sub> needs 3 ATP. So ${k} × 6 × 3 = ${atp} ATP.` }; },
    verify(p) { return p.k * 6 * 3; } },
  { id: 'ps-g02', type: 'nat', level: 3, format: 'integer', exams: E, sub: 'ATP and NADPH counts',
    make(rng) { const c = int(rng, 4, 30); return { c, q: `How many NADPH are used in the Calvin cycle to fix ${c} molecules of CO<sub>2</sub>?`, answer: 2 * c, tol: 0, sol: `Each CO<sub>2</sub> fixed needs 2 NADPH (for reduction of PGA). So ${c} × 2 = ${2 * c}.` }; },
    verify(p) { return p.c + p.c; } },
  { id: 'ps-g03', type: 'nat', level: 4, format: 'integer', exams: E, sub: 'C4 pathway',
    make(rng) { const k = int(rng, 1, 8); return { k, q: `How many ATP does a C4 plant use (C4 cycle plus Calvin cycle) to make ${k} molecules of glucose?`, answer: 30 * k, tol: 0, sol: `Per CO<sub>2</sub>: 3 ATP in the Calvin cycle and 2 ATP to regenerate PEP = 5 ATP. Per glucose: 6 × 5 = 30 ATP. For ${k} glucose: ${30 * k} ATP.` }; },
    verify(p) { return p.k * 6 * (3 + 2); } },
  { id: 'ps-g04', type: 'nat', level: 4, format: 'integer', exams: E, sub: 'light reaction',
    make(rng) { const w = int(rng, 2, 12) * 2; return { w, q: `How many electrons are released when ${w} molecules of water are split in the light reaction?`, answer: 2 * w, tol: 0, sol: `2H<sub>2</sub>O → 4H<sup>+</sup> + O<sub>2</sub> + 4e<sup>−</sup>, so each water gives 2 electrons. ${w} × 2 = ${2 * w} electrons.` }; },
    verify(p) { return (p.w / 2) * 4; } },
  { id: 'ps-g05', type: 'nat', level: 4, format: 'integer', exams: E, sub: 'light reaction',
    make(rng) { const o = int(rng, 2, 9); return { o, q: `A leaf releases ${o} molecules of O<sub>2</sub> by non-cyclic photophosphorylation. How many NADPH could be made from the electrons released?`, answer: 2 * o, tol: 0, sol: `Each O<sub>2</sub> comes with 4 electrons. Each NADPH needs 2 electrons. So ${o} × 4 ÷ 2 = ${2 * o} NADPH.` }; },
    verify(p) { return (p.o * 4) / 2; } },
  { id: 'ps-g06', type: 'mcq', level: 3, format: 'single', exams: E, sub: 'ATP and NADPH counts',
    make(rng) { const t = int(rng, 2, 8); const c = 3 * t; const o = shuffleOpts(rng, `${3 * c} ATP and ${2 * c} NADPH`, [`${2 * c} ATP and ${3 * c} NADPH`, `${3 * c} ATP and ${3 * c} NADPH`, `${2 * c} ATP and ${2 * c} NADPH`]); return { c, q: `${c} molecules of CO<sub>2</sub> are fixed by a C3 plant. How much ATP and NADPH are used?`, options: o.options, answer: o.answer, sol: `Per CO<sub>2</sub>: 3 ATP and 2 NADPH. For ${c}: ${3 * c} ATP and ${2 * c} NADPH. Swapping the numbers or leaving out the regeneration ATP gives the wrong options.` }; },
    verify(p) { return p.options.indexOf(`${p.c * 3} ATP and ${p.c * 2} NADPH`); } },
];
// ===== EXPANSION (round 2) =====
const hm = (level, sub, q, correct, wrongs, sol, trap) => mc(level, sub, q, correct, wrongs, sol, trap, 'statements');
// ---- Level 2
mc(2, 'early experiments', 'In Engelmann\'s experiment with Cladophora and aerobic bacteria under a prism, the bacteria gathered mainly in the', 'blue and red regions of the spectrum', ['green and yellow regions', 'ultraviolet region only', 'infrared region'], 'Oxygen is released where photosynthesis is fastest. Aerobic bacteria gathered there: in the blue and red regions, where chlorophyll absorbs best. This was the first action spectrum.');
mc(2, 'Calvin cycle', 'The enzyme that fixes CO2 in the Calvin cycle of C3 plants is', 'RuBisCO (RuBP carboxylase-oxygenase)', ['PEP carboxylase', 'ATP synthase', 'NADP reductase'], 'RuBisCO adds CO2 to the 5-carbon RuBP. It is the most abundant enzyme on earth. PEP carboxylase is the primary fixing enzyme of C4 plants.');
mc(2, 'Calvin cycle', 'The number of carbon atoms in RuBP, PGA, PEP and OAA are respectively', '5, 3, 3 and 4', ['3, 5, 4 and 3', '5, 3, 4 and 3', '6, 3, 3 and 4'], 'RuBP is a 5-carbon sugar, PGA and PEP are 3-carbon compounds, and OAA is a 4-carbon acid.', 'C3 and C4 plants are named after the first stable compound: PGA (3C) or OAA (4C).');
mc(2, 'chloroplast', 'The photosystems of a chloroplast are located in the', 'thylakoid membranes', ['stroma', 'outer membrane', 'inner membrane only'], 'The light reaction takes place on the thylakoid membranes (grana and stroma lamellae), where PS I, PS II, the carriers and the ATP synthase lie.');
mc(2, 'C4 pathway', 'In the C4 pathway, the Calvin cycle takes place in the', 'bundle sheath cells', ['mesophyll cells', 'guard cells', 'epidermal cells'], 'CO2 is first fixed into OAA in the mesophyll, then released in the bundle sheath cells where the Calvin cycle occurs.');
mc(2, 'pigments', 'Chlorophyll b in a chromatogram of leaf pigments appears', 'yellow-green', ['bright or blue-green', 'yellow', 'yellow to yellow-orange'], 'Chlorophyll a: bright or blue-green. Chlorophyll b: yellow-green. Xanthophylls: yellow. Carotenoids: yellow to yellow-orange.');
mc(2, 'Calvin cycle', 'The Calvin cycle is also known as the', 'C3 cycle', ['C4 cycle', 'Z scheme', 'Krebs cycle'], 'The first stable product is the 3-carbon PGA, so the cycle is called the C3 cycle.');
mc(2, 'C4 pathway', 'The primary CO2 acceptor in C4 plants is', 'phosphoenol pyruvate (PEP), a 3-carbon compound', ['RuBP, a 5-carbon compound', 'oxaloacetic acid, a 4-carbon compound', 'pyruvic acid, a 3-carbon compound'], 'PEP carboxylase in mesophyll cells adds CO2 to PEP and gives OAA. In C3 plants the primary acceptor is RuBP.');
mc(2, 'chloroplast', 'The stroma lamellae of a chloroplast', 'connect the grana', ['are the outer membrane', 'make up the stroma', 'make the inner membrane'], 'Grana are stacks of thylakoids; the flat membranous tubules joining different grana are the stroma lamellae.');
mc(2, 'pigments', 'The accessory pigments of photosynthesis include', 'chlorophyll b, xanthophylls and carotenoids', ['chlorophyll a only', 'phycoerythrin only', 'anthocyanin'], 'Accessory pigments absorb light and pass the energy to chlorophyll a, and also protect chlorophyll from photo-oxidation.');
mc(2, 'photosynthesis basics', 'Photosynthesis in higher plants takes place mainly in the', 'chloroplasts of mesophyll cells of leaves', ['mitochondria of root cells', 'nuclei of guard cells only', 'cell wall of the epidermis'], 'Green leaves have chloroplasts in their mesophyll. Other green parts can photosynthesise too.');
mc(2, 'factors', 'Which of these is NOT a major external factor affecting photosynthesis?', 'Atmospheric nitrogen', ['Light', 'Carbon dioxide concentration', 'Temperature'], 'Light, CO2, temperature and water are the main external factors. Nitrogen gas from the air is not used in photosynthesis.');
mc(2, 'Calvin cycle', 'In the Calvin cycle the regeneration of RuBP needs', '1 ATP per RuBP (phosphorylation)', ['NADPH only', 'O2 only', 'light directly'], 'Regeneration of the CO2 acceptor RuBP needs one ATP for phosphorylation. For each CO2 fixed, the cycle needs 3 ATP and 2 NADPH in all.');

// ---- Level 3
mc(3, 'Calvin cycle', 'The three stages of the Calvin cycle, in order, are', 'carboxylation, reduction and regeneration', ['reduction, carboxylation and regeneration', 'regeneration, reduction and carboxylation', 'carboxylation, regeneration and reduction'], 'CO2 is first added to RuBP (carboxylation), the PGA is reduced to sugar using ATP and NADPH (reduction), and RuBP is regenerated using ATP.');
mc(3, 'Calvin cycle', 'In the Calvin cycle, how many ATP and NADPH are used for the REDUCTION step for each CO2 fixed?', '2 ATP and 2 NADPH', ['3 ATP and 2 NADPH', '1 ATP and 2 NADPH', '2 ATP and 1 NADPH'], 'Each PGA needs one ATP (to make 1,3-bisphosphoglycerate) and one NADPH. Per CO2 fixed, 2 ATP and 2 NADPH are used in reduction; one more ATP is used in regeneration.', 'The total is 3 ATP but only 2 are used in reduction.');
mc(3, 'Calvin cycle', 'To make one molecule of glucose, how many CO2, ATP and NADPH does a C3 plant use in the Calvin cycle?', '6 CO2, 18 ATP and 12 NADPH', ['6 CO2, 12 ATP and 18 NADPH', '12 CO2, 18 ATP and 12 NADPH', '6 CO2, 30 ATP and 12 NADPH'], 'Per CO2: 3 ATP and 2 NADPH. For six: 18 ATP and 12 NADPH.', '30 ATP is for the C4 plants.');
mc(3, 'C4 pathway', 'Per CO2 fixed, a C4 plant needs', '5 ATP and 2 NADPH', ['3 ATP and 2 NADPH', '5 ATP and 3 NADPH', '2 ATP and 5 NADPH'], 'The Calvin cycle needs 3 ATP and 2 NADPH, and regeneration of PEP from pyruvate in the mesophyll needs 2 ATP more: 5 ATP.', 'Two more ATP are for PEP regeneration.');
mc(3, 'C4 pathway', 'Kranz anatomy refers to', 'large bundle sheath cells forming a wreath around the vascular bundle', ['sunken stomata in cacti', 'thick cuticle on leaves', 'spongy mesophyll only'], 'In C4 plants, the bundle sheath cells have many chloroplasts and thick walls, are impervious to gases, and lack intercellular spaces.');
mc(3, 'C4 pathway', 'In a C4 plant, OAA formed in the mesophyll', 'is converted to malic or aspartic acid and is transported to the bundle sheath cells', ['goes directly to the stroma of mesophyll chloroplasts', 'is converted to RuBP', 'goes to the xylem'], 'OAA is changed to malic acid or aspartic acid, which moves into the bundle sheath cells and releases CO2 there.');
mc(3, 'C4 pathway', 'The 3-carbon compound formed in the bundle sheath after decarboxylation of the C4 acid is', 'pyruvic acid, which goes back to the mesophyll', ['PGA, which goes to the xylem', 'RuBP, which goes to the stomata', 'glucose, which goes to the mesophyll'], 'Pyruvate returns to the mesophyll and is converted to PEP with the use of ATP. The CO2 released enters the Calvin cycle.');
mc(3, 'C4 pathway', 'The optimum temperature range of C4 plants is about', '30 to 40 degrees Celsius', ['20 to 25 degrees Celsius', '5 to 10 degrees Celsius', '50 to 60 degrees Celsius'], 'C4 plants (e.g. maize, sorghum) do well in warm climates; C3 plants have an optimum temperature of about 20 to 25 degrees Celsius.');
mc(3, 'C4 pathway', 'Which of these is a typical C4 plant?', 'Maize', ['Wheat', 'Rice', 'Potato'], 'Maize, sorghum and sugarcane are C4 plants. Wheat, rice and potato are C3.');
mc(3, 'light reaction', 'The stroma lamellae contain', 'PS I and ATP synthase but little or no PS II and no NADP reductase', ['PS II and NADP reductase only', 'PS I and PS II both', 'only the water-splitting complex'], 'The stroma lamellae membranes lack PS II as well as NADP reductase, so only cyclic flow of electrons takes place there.');
mc(3, 'light reaction', 'NADP reductase, the enzyme that reduces NADP+, is located on the', 'stroma side of the thylakoid membrane', ['lumen side of the thylakoid membrane', 'outer membrane of the chloroplast', 'inner mitochondrial membrane'], 'NADP+ is reduced in the stroma, which also removes protons from the stroma, and this helps the proton gradient.');
mc(3, 'light reaction', 'The splitting of water in the light reaction takes place on', 'the inner (lumen) side of the thylakoid membrane, associated with PS II', ['the stroma side, associated with PS I', 'the outer membrane of the chloroplast', 'the stroma lamellae only'], 'Water splitting happens on the lumen side with PS II, so protons from water are released into the lumen.');
mc(3, 'light reaction', 'Besides water, the splitting of water into O2 needs', 'Mn2+, Ca2+ and Cl- ions', ['Fe3+, Zn2+ and Mg2+ only', 'K+ and Na+ only', 'Cu2+ and Mo6+'], 'The oxygen-evolving complex of PS II uses manganese, calcium and chloride ions, as stated in NCERT.');
mc(3, 'chemiosm', 'The CF0 part of the ATP synthase', 'forms a transmembrane channel for protons', ['is on the lumen side and catalyses water splitting', 'is the site of CO2 fixation', 'is found in the outer membrane of the chloroplast'], 'CF0 is embedded in the thylakoid membrane and forms the channel through which protons leave the lumen. CF1 projects on the stroma side and makes ATP.');
mc(3, 'pigments', 'An absorption spectrum differs from an action spectrum in that the absorption spectrum', 'shows light absorbed by a pigment, and the action spectrum shows the rate of photosynthesis at each wavelength', ['shows the rate of photosynthesis, and the action spectrum shows absorption', 'is the same for all pigments', 'is measured only in the dark'], 'The action spectrum resembles the combined absorption of all pigments and has peaks in the blue and red regions.', 'The action spectrum measures a response, not absorption.');
mc(3, 'pigments', 'Which of these is a function of carotenoids?', 'Absorbing light and protecting chlorophyll from photo-oxidation', ['Splitting water', 'Fixing CO2', 'Making ATP'], 'Carotenoids and xanthophylls absorb light and pass it on, and protect chlorophyll from photo-oxidation.');
mc(3, 'photorespiration', 'In photorespiration, the products of the oxygenase activity of RuBisCO are', 'one PGA and one phosphoglycolate', ['two PGA', 'one PGA and one OAA', 'two phosphoglycolate'], 'RuBisCO with O2 splits RuBP into one 3-carbon PGA and one 2-carbon phosphoglycolate, which is later processed in the peroxisome and mitochondrion.');
mc(3, 'photorespiration', 'Photorespiration differs from respiration in that photorespiration', 'releases CO2 and makes neither sugar nor ATP', ['produces many ATP', 'takes place in the dark', 'takes place only in animals'], 'In photorespiration there is neither synthesis of sugars nor of ATP; instead CO2 is released with the use of ATP. It is a wasteful process.', 'It is not an energy-yielding process.');
mc(3, 'photorespiration', 'Photorespiration is absent or negligible in C4 plants because', 'they have a mechanism that increases the concentration of CO2 at the RuBisCO site', ['their RuBisCO has no oxygenase activity at all', 'they do not have peroxisomes', 'they close their stomata the whole day'], 'The C4 pathway raises CO2 in the bundle sheath cells, so RuBisCO functions mainly as a carboxylase.');
mc(3, 'factors', 'Which of these is correct about light and C3 and C4 plants at low light intensity?', 'Light is the limiting factor for both; the rates are similar', ['C4 plants always have a much higher rate', 'C3 plants have a much higher rate', 'Neither responds to light'], 'At low light, light limits both types, so the response is the same. C4 plants gain at high light and high temperature.');
mc(3, 'early experiments', 'Julius von Sachs showed that the products of photosynthesis in green parts are', 'glucose, which is usually stored as starch', ['oxygen only', 'protein stored as seeds', 'fats stored as oil'], 'Sachs found that the green parts of plants make glucose, which is stored as starch.');
mc(3, 'early experiments', 'Cornelius van Niel showed in purple and green sulphur bacteria that', 'H2S, not H2O, is the hydrogen donor, and sulphur, not oxygen, is released', ['H2O is the donor and oxygen is released', 'CO2 is the donor and glucose is released', 'No donor is used'], 'He inferred that in green plants H2O is the hydrogen donor and the oxygen evolved comes from water.');
asr(3, 'light reaction', 'Cyclic photophosphorylation does not produce NADPH.', 'In cyclic flow the electron returns to PS I and not to NADP+.', 0, 'The electron cycles back to PS I via the cytochrome complex, so NADP+ is not reduced and no water is split. R explains A.');
asr(3, 'C4 pathway', 'C4 plants show little photorespiration.', 'CO2 is concentrated around RuBisCO in the bundle sheath cells.', 0, 'High CO2 around RuBisCO favours the carboxylase action. R explains A.');
asr(3, 'chloroplast', 'The enzymes of the Calvin cycle are found in the stroma.', 'The stroma is the site of fixation of CO2 into sugars.', 0, 'The stroma contains the enzymes for the synthesis of sugars and proteins. Both are true; R explains A.');
asr(3, 'pigments', 'Chlorophyll a is the primary pigment of photosynthesis.', 'Only chlorophyll a forms the reaction centre of the photosystems.', 0, 'The reaction centres are specialised chlorophyll a molecules (P680, P700), and the other pigments transfer energy to them. R explains A.');
stm(3, 'C4 pathway', 'PEP carboxylase has no affinity for O2.', 'RuBisCO has affinity for both CO2 and O2.', 0, 'PEP carboxylase fixes CO2 in the mesophyll with no oxygenase activity; RuBisCO can bind either CO2 or O2. Both are correct.');
stm(3, 'Calvin cycle', 'The Calvin cycle needs light directly.', 'It uses ATP and NADPH formed in the light reaction.', 3, 'The Calvin cycle does not use light directly (so it is called the dark reaction, though it stops without ATP and NADPH). Statement II is correct.');
stm(3, 'light reaction', 'PS I has the reaction centre P700.', 'PS II has the reaction centre P680.', 0, 'The reaction centres are named after the wavelength of maximum absorption: 700 nm and 680 nm.');
hm(3, 'light reaction', 'Consider these statements. (1) P680 is the reaction centre of PS II. (2) NADP reductase is on the stroma side. (3) The Z scheme starts at PS I. (4) Cyclic flow needs PS II. How many are correct?', 'Only two', ['Only three', 'Only one', 'All four'], '(1) and (2) are correct. (3) is wrong: non-cyclic flow starts at PS II. (4) is wrong: cyclic flow uses only PS I.', 'Z scheme: PS II then PS I.');
hm(3, 'C4 pathway', 'Consider these features. (1) Kranz anatomy (2) PEP carboxylase in mesophyll (3) Photorespiration is high (4) First stable product is a 4C acid. How many apply to C4 plants?', 'Three', ['Two', 'One', 'All four'], '(1), (2) and (4) are features of C4 plants. (3) is wrong: photorespiration is negligible.');
match(3, 'Calvin cycle', 'xm1', 'Stage and event', ['A. Carboxylation', 'B. Reduction', 'C. Regeneration', 'D. Photorespiration'], ['p. Addition of CO2 to RuBP', 'q. PGA to triose phosphate with ATP and NADPH', 'r. Formation of RuBP using ATP', 's. RuBisCO acts as an oxygenase'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Carboxylation: CO2 + RuBP. Reduction: PGA to sugar. Regeneration: RuBP. Photorespiration: oxygenation of RuBP.');
match(3, 'pigments', 'xm2', 'Pigment and colour in a chromatogram', ['A. Chlorophyll a', 'B. Chlorophyll b', 'C. Xanthophyll', 'D. Carotenoid'], ['p. Bright or blue-green', 'q. Yellow-green', 'r. Yellow', 's. Yellow to yellow-orange'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-p, B-r, C-q, D-s'], 'Chlorophyll a: blue-green; chlorophyll b: yellow-green; xanthophylls: yellow; carotenoids: yellow to orange.');
match(3, 'C4 pathway', 'xm3', 'Compound and its carbon number or role', ['A. PEP', 'B. OAA', 'C. RuBP', 'D. PGA'], ['p. 3C acceptor of CO2 in C4 plants', 'q. 4C first stable product of C4 plants', 'r. 5C acceptor of CO2 in C3 plants', 's. 3C first stable product of C3 plants'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'PEP is the 3C acceptor in C4 plants; OAA is the first 4C product; RuBP is the 5C acceptor in C3 plants; PGA is the first stable 3C product in C3.');

// ---- Level 4
mc(4, 'Calvin cycle', 'How many molecules of ATP and NADPH are needed for one molecule of triose phosphate (net, 3 CO2 fixed) in the Calvin cycle?', '9 ATP and 6 NADPH', ['6 ATP and 9 NADPH', '18 ATP and 12 NADPH', '9 ATP and 3 NADPH'], 'Three CO2: 3 x 3 = 9 ATP, and 3 x 2 = 6 NADPH. A net triose phosphate needs three turns.', 'Net gain is one 3C unit per three CO2.');
mc(4, 'C4 pathway', 'For fixing 6 CO2 into one molecule of glucose, a C4 plant uses', '30 ATP and 12 NADPH', ['18 ATP and 12 NADPH', '30 ATP and 18 NADPH', '12 ATP and 30 NADPH'], 'Each CO2 needs 5 ATP and 2 NADPH: 6 x 5 = 30 ATP; 6 x 2 = 12 NADPH.');
mc(4, 'light reaction', 'The number of electrons that must pass through the Z scheme to make 12 NADPH is', '24', ['12', '48', '6'], 'Each NADPH needs 2 electrons: 12 x 2 = 24. The electrons come from 12 H2O.');
mc(4, 'Calvin cycle', 'A radioactive 14CO2 is supplied to a C3 leaf for a few seconds. The first compound labelled is', 'PGA', ['RuBP', 'glucose', 'OAA'], 'The 14C appears first in the 3-carbon PGA, after carboxylation of RuBP.');
mc(4, 'C4 pathway', 'A radioactive 14CO2 is supplied for a few seconds to a maize leaf. The first compound labelled will be', 'OAA', ['PGA', 'RuBP', 'starch'], 'In C4 plants the CO2 is first fixed to PEP by PEP carboxylase, giving OAA.');
mc(4, 'C4 pathway', 'Which of the following is correct for C4 plants?', 'The bundle sheath chloroplasts carry out the Calvin cycle, and the mesophyll cells carry out the first carboxylation', ['The mesophyll cells carry out the Calvin cycle', 'There is no carboxylation in mesophyll', 'Calvin cycle is absent altogether'], 'C4 plants use both pathways: PEPcase in mesophyll and RuBisCO in the bundle sheath.');
mc(4, 'C4 pathway', 'Why is C4 photosynthesis more efficient at high temperatures and bright light?', 'CO2 is concentrated at RuBisCO, so oxygenase activity and photorespiration are minimal', ['RuBisCO is absent', 'The stomata remain open at night only', 'They lack chlorophyll in the mesophyll'], 'At high temperature the oxygenase activity of RuBisCO rises in C3 plants; in C4 plants the CO2 is concentrated, so loss is low.');
mc(4, 'factors', 'Law of limiting factors by Blackman says that if a process is conditioned by several factors, its rate is determined by', 'the factor nearest to its minimal value', ['the factor at its maximum value', 'the sum of all factors', 'the average of the factors'], 'Blackman (1905): the rate is limited by the factor that is in shortest supply.', 'It is the minimum, not the maximum.');
mc(4, 'factors', 'In bright light at a normal CO2 level of 0.03 to 0.04 per cent, what is the limiting factor for a C3 plant?', 'CO2 concentration', ['Light intensity', 'Oxygen', 'Chlorophyll b'], 'In strong light, the CO2 concentration limits the rate; increasing CO2 gives increased photosynthesis in C3 plants.');
mc(4, 'factors', 'About what fraction of the full sunlight is enough to saturate the light response of most plants?', 'Nearly 10 per cent', ['Nearly 90 per cent', 'Nearly 50 per cent', 'Nearly 1 per cent'], 'Except for plants in shade, light saturation occurs at 10 per cent of the full sunlight. Increased light beyond this causes photo-oxidation damage.');
mc(4, 'photosynthesis basics', 'Only a small part of the photosynthetically active radiation is converted to carbohydrate. The part is', 'about 2 to 10 per cent', ['about 50 to 60 per cent', 'about 90 per cent', 'about 100 per cent'], 'NCERT: of the PAR, only about 2 to 10 per cent is captured and converted into biomass.');
mc(4, 'chemiosm', 'In the chloroplast, a proton gradient is created across the thylakoid membrane through which of the following?', 'Splitting of water in the lumen, proton transport by plastoquinone, and removal of protons in the stroma by NADP reductase', ['Splitting of water in the stroma only', 'Entry of protons from the stroma to lumen by ATP synthase', 'Release of protons by RuBisCO in the stroma'], 'Three processes add to the gradient: water splitting releases H+ in the lumen; the electron carrier pumps H+ in as electrons flow; NADP reductase uses H+ in the stroma.');
mc(4, 'chemiosm', 'Which of these gives the correct comparison between ATP synthesis in chloroplasts and mitochondria?', 'In both, protons move down their gradient through the ATP synthase; in chloroplast the protons move from lumen to stroma', ['In both, protons move from the matrix to the intermembrane space through ATP synthase', 'Only chloroplasts use a proton gradient', 'In chloroplasts, the protons move from stroma to lumen through ATP synthase'], 'Protons accumulate in the lumen and pass out into the stroma through CF0, where CF1 makes ATP.');
mc(4, 'light reaction', 'Which statement about PS I and PS II is correct?', 'PS II uses P680 and is linked to water splitting; PS I uses P700 and reduces NADP+', ['PS I uses P680 and splits water', 'PS II reduces NADP+', 'PS I and PS II both split water'], 'In the Z scheme, PS II (P680) passes electrons to PS I (P700), which finally reduces NADP+.');
mc(4, 'light reaction', 'The electrons lost from the reaction centre of PS I in non-cyclic flow are finally accepted by', 'NADP+', ['O2', 'water', 'CO2'], 'The electron from PS I passes through a few carriers, and then NADP+ accepts them (with H+) to form NADPH.');
mc(4, 'photorespiration', 'The organelles involved in the photorespiratory pathway, in the order the glycolate travels, are', 'chloroplast, peroxisome and mitochondrion', ['mitochondrion, peroxisome and chloroplast', 'peroxisome, chloroplast and mitochondrion', 'chloroplast, mitochondrion and peroxisome'], 'Phosphoglycolate made in the chloroplast is converted in the peroxisome and mitochondrion, with release of CO2.');
mc(4, 'photorespiration', 'Which condition favours the oxygenase activity of RuBisCO?', 'High O2, low CO2 and high temperature', ['Low O2 and high CO2', 'Low light only', 'Low temperature and high CO2'], 'The relative concentrations of O2 and CO2 at the enzyme site determine whether RuBisCO acts as carboxylase or oxygenase. High temperature favours oxygenation.');
mc(4, 'pigments', 'In the paper chromatography of leaf pigments, the pigment that moves the farthest is', 'carotene (carotenoid)', ['chlorophyll a', 'chlorophyll b', 'xanthophyll'], 'Carotenes are the most non-polar and move the farthest up the paper with the solvent. They appear at the top of the chromatogram as the yellow to yellow-orange band.');
mc(4, 'light reaction', 'The light-harvesting complex of a photosystem contains', 'many pigment molecules bound to proteins, with all pigments except one chlorophyll a forming the antenna', ['one chlorophyll a molecule only', 'only carotenoids', 'only the water-splitting enzyme'], 'The LHC has hundreds of pigment molecules; one chlorophyll a molecule forms the reaction centre and the rest are antennae.');
mc(4, 'Calvin cycle', 'The product of the first carboxylation in C3 plants has how many carbons and what is its name?', 'Two molecules of PGA, each with 3 carbons', ['One molecule of OAA with 4 carbons', 'One molecule of RuBP with 5 carbons', 'One molecule of glucose with 6 carbons'], 'RuBP (5C) + CO2 gives an unstable 6C compound that splits into two PGA (3C each).');
asr(4, 'C4 pathway', 'The bundle sheath cells of C4 plants have thick walls without intercellular spaces.', 'This arrangement prevents the loss of CO2 released in the bundle sheath.', 0, 'The thick, impervious walls keep the concentrated CO2 in the bundle sheath. R explains A.');
asr(4, 'light reaction', 'Splitting of water into oxygen is linked to PS II.', 'Electrons from water are needed to replace those lost by the reaction centre of PS II.', 0, 'P680 loses electrons on excitation and gets them from water, which releases O2 and H+. R explains A.');
asr(4, 'factors', 'Increasing the CO2 above 450 microlitre per litre gives little further increase in photosynthesis in C3 plants.', 'The enzyme or light becomes limiting after that.', 0, 'At saturation, another factor (such as light or RuBisCO) becomes limiting. Blackman\'s law. R explains A.');
asr(4, 'photorespiration', 'In C3 plants photorespiration reduces the yield.', 'It produces neither ATP nor NADPH and releases CO2 fixed earlier.', 0, 'It is a wasteful process, which uses fixed carbon. R explains A.');
asr(4, 'chemiosm', 'ATP synthesis in chloroplast needs a proton gradient.', 'CF0 forms the channel and CF1 makes ATP when protons flow back to the stroma.', 0, 'The energy of the proton gradient drives the conformational change in CF1 to make ATP. R explains A.');
stm(4, 'C4 pathway', 'In C4 plants PEPcase is found in mesophyll cells.', 'RuBisCO is found in mesophyll cells of C4 plants.', 2, 'Statement I is correct. Statement II is wrong: RuBisCO is in the bundle sheath cells of C4 plants.');
stm(4, 'light reaction', 'Cyclic flow of electrons takes place in the stroma lamellae.', 'Non-cyclic flow of electrons mainly takes place in the grana.', 0, 'Stroma lamellae have PS I only; grana have PS I and II. Both are correct.');
stm(4, 'Calvin cycle', 'The conversion of 3-PGA to triose phosphate needs ATP and NADPH.', 'The conversion of PGA to triose phosphate needs light directly.', 2, 'The reduction uses ATP and NADPH (I correct). It does not need light directly (II incorrect).');
hm(4, 'photorespiration', 'Consider these statements. (1) RuBisCO has both carboxylase and oxygenase functions. (2) Photorespiration takes place in chloroplast, peroxisome and mitochondrion. (3) Photorespiration makes ATP. (4) Photorespiration is high in C4 plants. How many are correct?', 'Only two', ['Only three', 'Only one', 'All four'], '(1) and (2) are correct. (3) is wrong: no ATP is made. (4) is wrong: it is negligible in C4 plants.');
hm(4, 'Calvin cycle', 'Consider these statements. (1) RuBisCO is the most abundant enzyme on earth. (2) The first stable product in the Calvin cycle is PGA. (3) Regeneration of RuBP needs ATP. (4) NADPH is used in carboxylation. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. (4) is wrong: NADPH is used in reduction.');
match(4, 'C3 and C4', 'xm4', 'Feature and plant type', ['A. Kranz anatomy', 'B. First product PGA', 'C. Optimum temperature 20-25 degrees C', 'D. Saturates at about 360 microlitre per litre of CO2'], ['p. C3 plants only', 'q. C4 plants only', 'r. Both C3 and C4', 's. Neither'], 'A-q, B-p, C-p, D-q', ['A-p, B-q, C-q, D-p', 'A-q, B-p, C-r, D-q', 'A-q, B-r, C-p, D-q'], 'Kranz anatomy is in C4. PGA as the first product is in C3. The cooler optimum is for C3. Saturation at 360 is in C4.', 'Each option may be used more than once.');
match(4, 'light reaction', 'xm5', 'Component and location', ['A. NADP reductase', 'B. Water splitting complex', 'C. CF1', 'D. PS II'], ['p. Stroma side of thylakoid', 'q. Lumen side of thylakoid', 'r. Mainly in grana, not in stroma lamellae', 's. Matrix of the mitochondrion'], 'A-p, B-q, C-p, D-r', ['A-q, B-p, C-p, D-r', 'A-p, B-q, C-q, D-r', 'A-p, B-q, C-p, D-s'], 'NADP reductase and CF1 are on the stroma side. The water-splitting complex is on the lumen side. PS II is mostly in grana lamellae.', 'One option may be used more than once.');
match(4, 'early experiments', 'xm6', 'Scientist and contribution', ['A. Joseph Priestley', 'B. Jan Ingenhousz', 'C. T. W. Engelmann', 'D. Cornelius van Niel'], ['p. Plants restore air spoiled by a burning candle', 'q. Sunlight and green parts are needed', 'r. First action spectrum', 's. Hydrogen donor in bacteria is H2S'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Priestley: air restored. Ingenhousz: light and green parts. Engelmann: spectrum. Van Niel: bacteria with H2S.');
match(4, 'photosynthesis stages', 'xm7', 'Process and number', ['A. ATP per CO2 in C3', 'B. ATP per CO2 in C4', 'C. NADPH per CO2 in C3', 'D. NADPH per CO2 in C4'], ['p. 2', 'q. 3', 'r. 5', 's. 4'], 'A-q, B-r, C-p, D-p', ['A-r, B-q, C-p, D-p', 'A-q, B-r, C-p, D-s', 'A-q, B-q, C-p, D-p'], 'C3: 3 ATP and 2 NADPH. C4: 5 ATP and 2 NADPH.', 'Each option may be used more than once.');
pass('xp1', 'Passage: leaf anatomy of two plants', 'A student examines transverse sections of the leaves of two plants. In plant X the bundle sheath cells around the vascular bundles are small and have few chloroplasts; the mesophyll shows a palisade and spongy tissue. In plant Y the bundle sheath cells are large, thick-walled and have many chloroplasts, and they form a wreath around the vascular bundles. Plant Y grows well in a hot, bright climate.');
pq('xp1', 3, 'C4 pathway', 'Plant Y is most likely', 'a C4 plant, such as maize', ['a C3 plant, such as wheat', 'a CAM plant, such as potato', 'a plant without a Calvin cycle'], 'The wreath-like large bundle sheath cells (Kranz anatomy) with many chloroplasts are the mark of C4 plants.');
pq('xp1', 4, 'C4 pathway', 'In plant Y the Calvin cycle occurs in', 'the bundle sheath cells', ['the mesophyll cells', 'the guard cells', 'the epidermis'], 'In C4 plants CO2 released in the bundle sheath cells is fixed by RuBisCO.');
pq('xp1', 4, 'photorespiration', 'Compared with plant X, plant Y has', 'less photorespiration', ['more photorespiration', 'no mitochondria', 'no RuBisCO'], 'The CO2 concentrating mechanism of C4 plants makes oxygenase activity negligible.');
pass('xp2', 'Passage: an ATP experiment', 'Isolated thylakoids are first kept in a pH 4 solution so that the lumen becomes acidic. They are then quickly moved into a pH 8 solution in the dark, and ADP and phosphate are added. ATP is formed for a short while.');
pq('xp2', 3, 'chemiosm', 'ATP is formed because', 'a proton gradient has been made between the lumen and the outside', ['light has been absorbed in the dark', 'oxygen has been released', 'NADPH has been formed'], 'The lumen is acidic and the outside is alkaline, so there is a proton gradient even without light.');
pq('xp2', 4, 'chemiosm', 'The protons move during ATP formation', 'from the lumen to the outside (stroma side) through the ATP synthase', ['from the outside into the lumen through the ATP synthase', 'from the lumen to the outside through RuBisCO', 'from the stroma to the lumen through NADP reductase'], 'Protons flow out through CF0 and the CF1 knob projecting on the outer side makes ATP.');
pq('xp2', 4, 'chemiosm', 'If the thylakoid membrane were made leaky to protons before the shift to pH 8, ATP formation would', 'fail, since there would be no gradient', ['increase', 'continue unchanged', 'be doubled'], 'A leaky membrane cannot hold the gradient. No gradient, no ATP.');
pass('xp3', 'Passage: an experiment with leaf discs', 'Leaf discs of a C3 plant and a C4 plant are kept in separate closed chambers. Each chamber is given the same light and temperature of 35 degrees Celsius and the CO2 level is gradually reduced to a very low value. The C4 plant continues to fix CO2 down to a very low CO2 level, while the C3 plant stops net photosynthesis at a higher level.');
pq('xp3', 3, 'C4 pathway', 'The C4 plant continues because', 'PEP carboxylase has high affinity for CO2 and the plant concentrates CO2 at RuBisCO', ['it does not need CO2', 'it has no stomata', 'it uses H2S'], 'PEPcase captures CO2 efficiently and the C4 pathway increases CO2 at the RuBisCO site.');
pq('xp3', 4, 'photorespiration', 'The C3 plant stops net CO2 gain at a higher CO2 level because', 'the CO2 released by photorespiration balances the CO2 fixed', ['it has no RuBisCO', 'it has only PS II', 'it makes no ATP'], 'At low CO2 and high temperature, the oxygenase activity makes the CO2 loss equal to fixation: the CO2 compensation point is higher in C3 plants.');
pq('xp3', 4, 'factors', 'The limiting factor in these chambers as the CO2 falls is', 'CO2 concentration', ['light intensity', 'temperature', 'water'], 'Light and temperature are constant, so the declining CO2 sets the rate.');

// ---- Level 5
mc(5, 'light reaction', 'Which of the following correctly lists the sequence of electron carriers in non-cyclic photophosphorylation?', 'H2O, PS II, plastoquinone, cytochrome b6f, plastocyanin, PS I, ferredoxin, NADP+', ['H2O, PS I, plastoquinone, cytochrome b6f, plastocyanin, PS II, NADP+', 'PS II, H2O, ferredoxin, plastocyanin, PS I, NADP+', 'NADP+, PS I, cytochrome b6f, PS II, H2O'], 'Electrons flow from water to PS II, through plastoquinone and the cytochrome complex, to PS I, then to ferredoxin and NADP reductase to reduce NADP+.', 'The electrons flow downhill; PS II comes first.');
mc(5, 'Calvin cycle', 'If the supply of ATP is limited but NADPH is in excess in the stroma, the step of the Calvin cycle that would be most directly slowed is', 'the reduction of PGA and the regeneration of RuBP, both requiring ATP', ['the formation of OAA from PEP', 'the splitting of water', 'the formation of NADPH from NADP+'], 'ATP is needed in reduction (to form 1,3-bisphosphoglycerate) and in regeneration of RuBP.');
mc(5, 'Calvin cycle', 'How many carbon atoms of RuBP are in 6 molecules of RuBP, and how many 3C PGA are formed when they all fix CO2?', '30 carbon atoms and 12 PGA', ['30 carbon atoms and 6 PGA', '18 carbon atoms and 12 PGA', '36 carbon atoms and 12 PGA'], '6 x 5 = 30 C in RuBP. Each RuBP + CO2 gives 2 PGA: 6 x 2 = 12 PGA (36 C with the 6 new C from CO2).', 'Count RuBP carbons, not the sum with CO2.');
mc(5, 'C4 pathway', 'Which of the following does NOT occur in the mesophyll cells of a C4 plant?', 'Regeneration of RuBP in the Calvin cycle', ['Formation of OAA', 'Conversion of pyruvate to PEP', 'Carboxylation by PEPcase'], 'The Calvin cycle with RuBP regeneration occurs in the bundle sheath cells.');
mc(5, 'photorespiration', 'A leaf of a C3 plant is exposed to 21 per cent O2 and a low CO2 at high temperature. Compared with a leaf exposed to 2 per cent O2 and the same CO2, the first leaf will have', 'a lower net rate of photosynthesis because of higher photorespiration', ['a higher net rate of photosynthesis', 'the same net rate', 'no respiration'], 'At low O2, oxygenase activity is low and net photosynthesis is higher. At higher O2, RuBisCO acts more as an oxygenase.');
mc(5, 'pigments', 'In the absorption spectrum of chlorophyll a, there is very little absorption in the green region. This is consistent with', 'the green colour of the leaves, since green light is reflected and transmitted', ['green leaves being unable to photosynthesise', 'the leaves absorbing mostly green light', 'carotenoids absorbing in the infrared'], 'Chlorophylls absorb mainly blue and red light. The green light is not absorbed, so the leaves look green.');
mc(5, 'early experiments', 'Engelmann concluded from his experiment that', 'oxygen is released in the regions where chlorophyll absorbs light, so those are the effective wavelengths', ['green light is the most effective', 'photosynthesis does not need light', 'oxygen comes from CO2'], 'The bacteria gather where O2 is released, at the blue and red parts of the spectrum.');
mc(5, 'light reaction', 'Which of these is the CORRECT product of the splitting of 4 molecules of water in the light reaction?', '8 H+, 2 O2 and 8 electrons', ['4 H+, 4 O2 and 4 electrons', '8 H+, 4 O2 and 8 electrons', '4 H+, 2 O2 and 8 electrons'], 'Each 2H2O gives 4H+ + O2 + 4e-. Four H2O: 2 sets: 8 H+, 2 O2 and 8 e-.', 'Two water molecules give one O2.');
asr(5, 'light reaction', 'The reaction centres of PS I and PS II are made of the same pigment, chlorophyll a, but they differ in their absorption peaks.', 'Chlorophyll a in the two reaction centres is associated with different proteins.', 0, 'P680 and P700 are both chlorophyll a molecules whose absorption peak is tuned by the protein environment. R explains A.');
asr(5, 'C4 pathway', 'C4 plants need more ATP than C3 plants per CO2 fixed.', 'Two additional ATP are used in the regeneration of PEP from pyruvate.', 0, 'The C4 pathway adds 2 ATP per CO2 to the 3 ATP of the Calvin cycle. R explains A.');
asr(5, 'Calvin cycle', 'The Calvin cycle can continue for a short time in the dark.', 'ATP and NADPH formed in light are present in the stroma.', 0, 'Stored ATP and NADPH can drive the cycle briefly after light is turned off. R explains A.');
stm(5, 'light reaction', 'The oxygen released in the light reaction comes from CO2.', 'Water is the source of the oxygen released in the light reaction.', 3, 'The oxygen comes from water (van Niel and later isotope experiments). Statement I is incorrect and Statement II is correct.');
stm(5, 'chloroplast', 'The ATP synthase of the thylakoid has its CF1 on the stroma side.', 'The water-splitting complex is on the lumen side.', 0, 'Both are correct; this arrangement lets protons accumulate in the lumen.');
hm(5, 'C4 pathway', 'Consider these statements. (1) RuBisCO of C4 plants is in the bundle sheath. (2) PEPcase is in the bundle sheath. (3) C4 plants use 5 ATP per CO2. (4) C4 plants show Kranz anatomy. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (3) and (4) are correct. (2) is wrong: PEPcase is in mesophyll cells.');
hm(5, 'light reaction', 'Consider these statements. (1) Cyclic photophosphorylation makes ATP only. (2) Non-cyclic makes ATP and NADPH. (3) Non-cyclic releases O2. (4) Cyclic involves PS II. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. (4) is wrong: cyclic flow involves PS I only.');
match(5, 'light reaction', 'xm8', 'Type of flow and features', ['A. Non-cyclic flow', 'B. Cyclic flow', 'C. Z scheme', 'D. Stroma lamellae'], ['p. ATP only', 'q. ATP, NADPH and O2', 'r. PS II to PS I in a zig-zag energy diagram', 's. PS I only, no NADP reductase'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-q, B-r, C-p, D-s'], 'Non-cyclic gives ATP, NADPH and O2; cyclic only ATP; the Z scheme describes the energy path from PS II to PS I; stroma lamellae have PS I but no NADP reductase.');
mc(4, 'light reaction', 'How many molecules of O2 are released when 12 NADPH are made by non-cyclic photophosphorylation?', '6', ['3', '12', '24'], 'Each NADPH needs 2 electrons, so 12 NADPH needs 24 electrons. Each O2 released (from 2 H2O) supplies 4 electrons: 24/4 = 6 O2.', 'Do not divide by 2: one O2 gives four electrons.');
mc(4, 'Calvin cycle', 'If the supply of ATP and NADPH from the light reaction is stopped, the Calvin cycle of a leaf will', 'stop after a short time, although light is not used directly in it', ['continue for hours using only light', 'speed up', 'switch over to the C4 cycle'], 'Reduction and regeneration need ATP and NADPH, which are made in the light reaction. Stored supplies last only briefly.');
match(4, 'light reaction', 'xm10', 'Component and feature', ['A. PS II', 'B. PS I', 'C. Cytochrome complex', 'D. ATP synthase'], ['p. Reaction centre P680', 'q. Reaction centre P700', 'r. Carries electrons between PS II and PS I and helps move protons', 's. CF0 channel and CF1 head'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'PS II has P680, PS I has P700; the cytochrome complex is the carrier between them; ATP synthase has CF0 (channel) and CF1 (catalytic head).');
match(4, 'factors', 'xm11', 'Quantity and value', ['A. Light saturation of most plants', 'B. CO2 saturation of C4 plants', 'C. Optimum temperature of C3 plants', 'D. Range of PAR'], ['p. About 10 per cent of full sunlight', 'q. About 360 microlitre per litre', 'r. About 20 to 25 degrees Celsius', 's. 400 to 700 nm'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'NCERT values: saturation at about 10 per cent of full sunlight; C4 saturates at about 360 microlitre per litre; C3 optimum 20 to 25 degrees; PAR 400 to 700 nm.');

export default { topic: 'photosynthesis', groups, items, gens };
